using System;
using System.Collections.Generic;
using System.Globalization;
using System.Runtime.CompilerServices;
using UnityEngine;

public static class Localization
{
	private const string PrefKey = "armorsim.language";

	[CompilerGenerated]
	private static Action m_OnLanguageChanged;

	public static readonly Language[] All;

	private static Language _current;

	private static bool _loaded;

	private static Language _cultureLang;

	private static CultureInfo _culture;

	private static readonly Dictionary<string, string[]> Table;

	public static Language Current
	{
		get
		{
			EnsureLoaded();
			return _current;
		}
	}

	public static CultureInfo Culture
	{
		get
		{
			Language lang = Current;
			if (_culture == null || _cultureLang != lang)
			{
				try
				{
					string name;
					switch (lang)
					{
					case Language.EN:
						name = "en-US";
						break;
					case Language.TT:
						name = "ru-RU";
						break;
					case Language.DE:
						name = "de-DE";
						break;
					case Language.PL:
						name = "pl-PL";
						break;
					default:
						name = "ru-RU";
						break;
					}
					_culture = CultureInfo.GetCultureInfo(name);
				}
				catch (CultureNotFoundException)
				{
					_culture = CultureInfo.InvariantCulture;
				}
				_cultureLang = lang;
			}
			return _culture;
		}
	}

	public static int KeyCount => Table.Count;

	public static event Action OnLanguageChanged
	{
		[CompilerGenerated]
		add
		{
			m_OnLanguageChanged = (Action)Delegate.Combine(m_OnLanguageChanged, value);
		}
		[CompilerGenerated]
		remove
		{
			m_OnLanguageChanged = (Action)Delegate.Remove(m_OnLanguageChanged, value);
		}
	}

	public static string NativeName(Language l)
	{
		switch (l)
		{
		case Language.RU:
			return "Русский";
		case Language.EN:
			return "English";
		case Language.TT:
			return "Татарча";
		case Language.DE:
			return "Deutsch";
		case Language.PL:
			return "Polski";
		default:
			return l.ToString();
		}
	}

	public static string ShortCode(Language l)
	{
		switch (l)
		{
		case Language.RU:
			return "RU";
		case Language.EN:
			return "EN";
		case Language.TT:
			return "TT";
		case Language.DE:
			return "DE";
		case Language.PL:
			return "PL";
		default:
			return "??";
		}
	}

	private static void EnsureLoaded()
	{
		if (_loaded)
		{
			return;
		}
		_loaded = true;
		int saved = PlayerPrefs.GetInt(PrefKey, -1);
		if (saved >= 0 && saved < All.Length)
		{
			_current = (Language)saved;
		}
		else
		{
			_current = DetectSystemLanguage();
		}
	}

	private static Language DetectSystemLanguage()
	{
		SystemLanguage language = Application.systemLanguage;
		if (language == SystemLanguage.German)
		{
			return Language.DE;
		}
		if (language == SystemLanguage.Polish)
		{
			return Language.PL;
		}
		return language == SystemLanguage.Russian ? Language.RU : Language.EN;
	}

	public static void SetLanguage(Language lang)
	{
		EnsureLoaded();
		if (_current == lang)
		{
			return;
		}
		_current = lang;
		PlayerPrefs.SetInt(PrefKey, (int)lang);
		PlayerPrefs.Save();
		m_OnLanguageChanged?.Invoke();
	}

	public static string T(string key)
	{
		EnsureLoaded();
		if (string.IsNullOrEmpty(key))
		{
			return string.Empty;
		}
		if (!Table.TryGetValue(key, out string[] cells))
		{
			return "#" + key;
		}
		string value = cells[(int)_current];
		if (!string.IsNullOrEmpty(value))
		{
			return value;
		}
		return cells[1];
	}

	public static string T(string key, params object[] args)
	{
		string format = T(key);
		try
		{
			return string.Format(Culture, format, args);
		}
		catch (FormatException)
		{
			return format;
		}
	}

	public static bool HasKey(string key)
	{
		return !string.IsNullOrEmpty(key) && Table.ContainsKey(key);
	}

	public static string[] LanguageCodes()
	{
		string[] result = new string[All.Length];
		for (int i = 0; i < All.Length; i++)
		{
			result[i] = ShortCode(All[i]);
		}
		return result;
	}

	public static List<MissingGlyph> AuditFontCoverage(Func<int, bool> hasGlyph)
	{
		return FontCoverage.Audit(Table, LanguageCodes(), hasGlyph);
	}

	public static bool CellEmpty(string key, Language lang)
	{
		if (!Table.TryGetValue(key, out string[] cells) || lang < 0 || (int)lang >= cells.Length)
		{
			return true;
		}
		return string.IsNullOrEmpty(cells[(int)lang]);
	}

	public static List<string> FindIncompleteKeys()
	{
		List<string> result = new List<string>();
		foreach (KeyValuePair<string, string[]> row in Table)
		{
			if (row.Value.Length < All.Length)
			{
				result.Add(row.Key);
				continue;
			}
			for (int i = 0; i < All.Length; i++)
			{
				if (string.IsNullOrEmpty(row.Value[i]))
				{
					result.Add(row.Key);
					break;
				}
			}
		}
		return result;
	}

