		{ "aero.error.normals", new string[5] { "Нормали вывернуты: {0} из {1} первых попаданий. Нажмите «Развернуть нормали».", "Inverted normals at {0} of {1} first hits. Select Reverse normals.", "{1} беренче тиюнең {0} очрагында нормальләр кирегә карый. «Нормальләрне кире бору»ны сайлагыз.", "Umgekehrte Normalen bei {0} von {1} ersten Treffern. Normalen umkehren wählen.", "Odwrócone normalne: {0} z {1} pierwszych trafień. Wybierz Odwróć normalne." } },
		{ "aero.error.drag", new string[5] { "Получено отрицательное сопротивление. Расчёт остановлен, результат не показан.", "Negative resistance detected. Calculation stopped; no result is displayed.", "Тискәре каршылык килеп чыкты. Исәпләү туктатылды, нәтиҗә күрсәтелми.", "Negativer Widerstand erkannt. Berechnung gestoppt; kein Ergebnis angezeigt.", "Wykryto ujemny opór. Obliczenia zatrzymano; wynik nie jest wyświetlany." } },
		{ "aero.error.calculation", new string[5] { "Недопустимые данные или результат расчёта. Числа не показаны.", "Invalid calculation input or result. No numbers are displayed.", "Исәпләү мәгълүматлары яки нәтиҗәсе яраксыз. Саннар күрсәтелми.", "Ungültige Berechnungsdaten oder ungültiges Ergebnis. Keine Zahlen angezeigt.", "Nieprawidłowe dane lub wynik obliczeń. Liczby nie są wyświetlane." } },
		{ "aero.error.resolution", new string[5] { "Сетка {0} недопустима: нужно от {1} до {2} лучей по стороне.", "Invalid grid {0}: each side needs {1} to {2} rays.", "{0} челтәре яраксыз: һәр якта {1}–{2} нур булырга тиеш.", "Ungültiges Raster {0}: pro Seite sind {1} bis {2} Strahlen erforderlich.", "Nieprawidłowa siatka {0}: każdy bok musi mieć od {1} do {2} promieni." } },
