		{ "flat.quality.hint_coarse", new string[5] { "Шаг частиц 0.5 мм. Расчёт — десятки секунд.", "Particle step 0.5 mm. The solve takes tens of seconds.", "Кисәкчек адымы 0.5 мм. Исәпләү — дистәләрчә секунд.", "Teilchenschritt 0,5 mm. Die Berechnung dauert mehrere zehn Sekunden.", "Krok cząstek 0,5 mm. Obliczenia trwają dziesiątki sekund." } },
		{ "flat.quality.hint_fine", new string[5] { "Шаг частиц 0.29 мм — частиц втрое больше. Расчёт в несколько раз дольше обычного.", "Particle step 0.29 mm — three times as many particles. The solve takes several times longer than normal.", "Кисәкчек адымы 0.29 мм — кисәкчекләр өч тапкыр күбрәк. Исәпләү гадәтидән берничә тапкыр озаграк.", "Teilchenschritt 0,29 mm — dreimal so viele Teilchen. Die Berechnung dauert ein Mehrfaches länger als normal.", "Krok cząstek 0,29 mm — trzy razy więcej cząstek. Obliczenia trwają kilka razy dłużej niż zwykle." } },
