		{ "aim.hint_line", new string[5] { "Выстрел по линии сцены: старт из сборки, полёт по +Z. «Свободно» - стрелять с любой стороны.", "Shot along the scene line: start from the build, flight along +Z. «Free aim» - shoot from any side.", "Сәхнә сызыгы буенча ату: старт җыелмадан, очыш +Z буенча. «Ирекле» - теләсә кайсы яктан ату.", "Schuss entlang der Szenenlinie: Start aus dem Aufbau, Flug entlang +Z. «Frei» - von jeder Seite schießen.", "Strzał wzdłuż linii sceny: start z zestawu, lot wzdłuż +Z. «Swobodnie» - strzał z dowolnej strony." } },
		{ "aim.hint_free", new string[5] { "Азимут «+» - вправо (к +X), возвышение «+» - сверху вниз, 90° - отвесно. Старт - за {0} м до точки прицела.", "Azimuth «+» turns right (toward +X), elevation «+» points down, 90° is straight down. The start is {0} m before the aim point.", "Азимут «+» - уңга (+X ягына), биеклек «+» - өстән аска, 90° - туп-туры. Старт төзәү ноктасыннан {0} м алда.", "Azimut «+» nach rechts (zu +X), Erhöhung «+» nach unten, 90° senkrecht. Der Start liegt {0} m vor dem Zielpunkt.", "Azymut «+» w prawo (ku +X), elewacja «+» w dół, 90° pionowo. Start {0} m przed punktem celowania." } },
