		{ "workshop.publishing", new string[5] { "Выгружаю «{0}» в мастерскую…", "Uploading '{0}' to the Workshop…", "«{0}» остаханәгә җибәрелә…", "Lade „{0}“ in den Workshop hoch…", "Wysyłam „{0}” do Warsztatu…" } },
		{ "workshop.published", new string[5] { "Выложено: «{0}». Страница предмета открыта в Steam.", "Published: '{0}'. The item page is open in Steam.", "Урнаштырылды: «{0}». Предмет бите Steamда ачылды.", "Veröffentlicht: „{0}“. Die Eintragsseite ist in Steam geöffnet.", "Opublikowano: „{0}”. Strona przedmiotu jest otwarta w Steam." } },
		{ "workshop.updated", new string[5] { "Обновлено: «{0}».", "Updated: '{0}'.", "Яңартылды: «{0}».", "Aktualisiert: „{0}“.", "Zaktualizowano: „{0}”." } },
		{ "workshop.published_hidden", new string[5] { "Предмет создан, но НЕ ВИДЕН НИКОМУ: не принято соглашение мастерской Steam. Страница соглашения открыта — примите его, и предмет появится.", "The item was created but is VISIBLE TO NO ONE: the Steam Workshop legal agreement has not been accepted. The agreement page is open — accept it and the item will appear.", "Предмет ясалды, ләкин БЕРКЕМГӘ ДӘ КҮРЕНМИ: Steam остаханәсе килешүе кабул ителмәгән. Килешү бите ачылды — аны кабул итегез, һәм предмет күренер.", "Der Eintrag wurde erstellt, ist aber FÜR NIEMANDEN SICHTBAR: Die Workshop-Vereinbarung von Steam wurde nicht angenommen. Die Seite ist geöffnet — nehmen Sie sie an, dann erscheint der Eintrag.", "Przedmiot powstał, ale NIE JEST WIDOCZNY DLA NIKOGO: nie zaakceptowano umowy Warsztatu Steam. Strona umowy jest otwarta — zaakceptuj ją, a przedmiot się pojawi." } },
		{ "workshop.reject.no_steam", new string[5] { "Нужен Steam: игра запущена без клиента Steam или собрана без поддержки мастерской.", "Steam is required: the game is running without the Steam client, or was built without Workshop support.", "Steam кирәк: уен Steam клиентыннан башка җибәрелгән яки остаханә ярдәменнән башка җыелган.", "Steam wird benötigt: Das Spiel läuft ohne Steam-Client oder wurde ohne Workshop-Unterstützung gebaut.", "Wymagany jest Steam: gra działa bez klienta Steam albo została zbudowana bez obsługi Warsztatu." } },
		{ "workshop.reject.preset", new string[5] { "Пресет не выкладывается: он принадлежит игре, а не игроку.", "A preset cannot be published: it belongs to the game, not to the player.", "Пресет урнаштырылмый: ул уенга карый, уенчыга түгел.", "Eine Vorlage lässt sich nicht veröffentlichen: Sie gehört dem Spiel, nicht dem Spieler.", "Szablonu nie można opublikować: należy do gry, nie do gracza." } },
		{ "workshop.reject.empty", new string[5] { "В сборке нет ни одного объекта — выкладывать нечего.", "The layout has no objects — there is nothing to publish.", "Җыелмада бер объект та юк — урнаштырырга нәрсә юк.", "Der Aufbau enthält kein einziges Objekt — es gibt nichts zu veröffentlichen.", "Układ nie zawiera żadnego obiektu — nie ma czego publikować." } },
		{ "workshop.reject.nothing", new string[5] { "Нечего выкладывать: сохранение пустое.", "Nothing to publish: the save is empty.", "Урнаштырырга нәрсә юк: сакланма буш.", "Nichts zu veröffentlichen: Der Speicherstand ist leer.", "Nie ma czego publikować: zapis jest pusty." } },
		{ "workshop.reject.busy", new string[5] { "Идёт другая выгрузка — дождитесь её конца.", "Another upload is in progress — wait for it to finish.", "Башка җибәрү бара — аның ахырын көтегез.", "Ein anderer Upload läuft — warten Sie, bis er fertig ist.", "Trwa inne wysyłanie — poczekaj na jego koniec." } },
		{ "workshop.reject.failed", new string[5] { "Steam отказал. Причина — в журнале.", "Steam refused. The reason is in the log.", "Steam баш тартты. Сәбәбе — журналда.", "Steam hat abgelehnt. Der Grund steht im Protokoll.", "Steam odmówił. Powód jest w dzienniku." } },
		{ "workshop.reject.write_failed", new string[5] { "Не удалось собрать папку предмета. Подробность — в журнале.", "Could not build the item folder. Details are in the log.", "Предмет папкасын җыеп булмады. Тулырак — журналда.", "Der Eintragsordner ließ sich nicht erstellen. Einzelheiten stehen im Protokoll.", "Nie udało się zbudować folderu przedmiotu. Szczegóły w dzienniku." } },
		{ "workshop.reject.no_files", new string[5] { "Файлы предмета ещё не скачаны.", "The item files are not downloaded yet.", "Предмет файллары әле йөкләнмәгән.", "Die Dateien des Eintrags sind noch nicht heruntergeladen.", "Pliki przedmiotu nie zostały jeszcze pobrane." } },
		{ "workshop.reject.no_manifest", new string[5] { "Это не предмет ArmorSim: в папке нет workshop.json.", "Not an ArmorSim item: the folder has no workshop.json.", "Бу ArmorSim предметы түгел: папкада workshop.json юк.", "Kein ArmorSim-Eintrag: Im Ordner fehlt workshop.json.", "To nie przedmiot ArmorSim: w folderze brak workshop.json." } },
		{ "workshop.reject.no_entry", new string[5] { "В предмете нет сборки брони.", "The item contains no armour layout.", "Предметта броня җыелмасы юк.", "Der Eintrag enthält keinen Panzerungsaufbau.", "Przedmiot nie zawiera układu pancerza." } },
		{ "workshop.reject.no_version", new string[5] { "В предмете не записан номер формата — читать его нечем.", "The item records no format number — there is nothing to read it with.", "Предметта формат номеры язылмаган — аны укырга нәрсә юк.", "Der Eintrag nennt keine Formatnummer — es gibt nichts, womit er zu lesen wäre.", "Przedmiot nie podaje numeru formatu — nie ma czym go odczytać." } },
		{ "workshop.reject.newer", new string[5] { "Предмет сделан более новой версией игры. Обновите игру.", "The item was made by a newer version of the game. Update the game.", "Предмет уенның яңарак версиясендә ясалган. Уенны яңартыгыз.", "Der Eintrag stammt aus einer neueren Version des Spiels. Aktualisieren Sie das Spiel.", "Przedmiot powstał w nowszej wersji gry. Zaktualizuj grę." } },
		{ "workshop.reject.malformed", new string[5] { "Предмет не читается: файл испорчен или собран не этой игрой.", "The item does not read: the file is damaged or was not made by this game.", "Предмет укылмый: файл бозылган яки бу уен ясамаган.", "Der Eintrag ist nicht lesbar: Die Datei ist beschädigt oder stammt nicht aus diesem Spiel.", "Przedmiot się nie wczytuje: plik jest uszkodzony albo nie pochodzi z tej gry." } },
		{ "workshop.reject.family_mismatch", new string[5] { "Предмет противоречит сам себе: карточка и сборка называют разные режимы.", "The item contradicts itself: the card and the layout name different modes.", "Предмет үзенә каршы килә: карточка белән җыелма төрле режимнарны атый.", "Der Eintrag widerspricht sich: Karte und Aufbau nennen verschiedene Modi.", "Przedmiot przeczy sam sobie: karta i układ podają różne tryby." } },
		{ "workshop.reject.unreadable", new string[5] { "Файлы предмета не читаются: нет доступа.", "The item files cannot be read: no access.", "Предмет файллары укылмый: рөхсәт юк.", "Die Dateien des Eintrags sind nicht lesbar: kein Zugriff.", "Nie można odczytać plików przedmiotu: brak dostępu." } },
		{ "about.title", new string[5] { "О РАЗРАБОТЧИКАХ", "ABOUT", "ЭШКӘРТҮЧЕЛӘР ТУРЫНДА", "ÜBER DIE ENTWICKLER", "O TWÓRCACH" } },
		{ "about.role_lead", new string[5] { "Автор проекта: физика, дизайн, баллистика", "Project lead: physics, design, ballistics", "Проект авторы: физика, дизайн, баллистика", "Projektleitung: Physik, Design, Ballistik", "Autor projektu: fizyka, projekt, balistyka" } },
		{ "about.body", new string[5] { "ARMOUR SIMULATOR — песочница терминальной баллистики. Пробитие считается по аналитическим моделям (Алексеевский–Тейт, кавитационное расширение, Грэди), а не по декоративным формулам: эрозия стержня, рикошет по критерию пластического шарнира, откол и петалинг выводятся из физики удара.\n\nКаждая константа в движке помечена как измеренная, выведенная или оценочная — со ссылкой на источник.", "ARMOUR SIMULATOR is a terminal ballistics sandbox. Penetration is computed with analytical models (Alekseevskii-Tate, cavity expansion, Grady) rather than decorative formulas: rod erosion, plastic-hinge ricochet, spall and petalling all follow from impact physics.\n\nEvery constant in the engine is tagged measured, derived or estimated, with a source citation.", "ARMOUR SIMULATOR — терминаль баллистика мәйданчыгы. Тишү аналитик модельләр буенча исәпләнә (Алексеевский–Тейт, куыш киңәю, Грэди): стерженьнең ашалуы, рикошет, кубу һәм петалинг бәрелеш физикасыннан килеп чыга.\n\nДвигательдәге һәр константа үлчәнгән, чыгарылган яки бәяләнгән дип билгеләнгән — чыганагы белән.", "ARMOUR SIMULATOR ist ein Sandkasten für Endballistik. Der Durchschlag wird mit analytischen Modellen berechnet (Alekseevskii-Tate, Hohlraumexpansion, Grady) statt mit dekorativen Formeln: Stab-Erosion, Abpraller nach dem Fließgelenk-Kriterium, Abplatzung und Petalling folgen aus der Aufprallphysik.\n\nJede Konstante ist als gemessen, hergeleitet oder geschätzt markiert - mit Quellenangabe.", "ARMOUR SIMULATOR to piaskownica balistyki końcowej. Przebicie liczone jest modelami analitycznymi (Alekseevskii-Tate, rozszerzanie kawerny, Grady), a nie ozdobnymi wzorami: erozja rdzenia, rykoszet wg kryterium przegubu plastycznego, odprysk i petaling wynikają z fizyki uderzenia.\n\nKażda stała w silniku jest oznaczona jako zmierzona, wyprowadzona lub szacowana - ze źródłem." } },
