		{ "controls.orbit_button", new string[5] { "Кнопка вращения камеры", "Camera orbit button", "", "Maustaste zum Drehen der Kamera", "Przycisk obrotu kamery" } },
		{ "controls.orbit_button_hint", new string[5] { "Отдали правую камере — она перестаёт отменять захват плиты; отмена остаётся на Esc.", "Give the right button to the camera and it stops cancelling a plate grab; Esc still cancels.", "", "Gibt man die rechte Taste der Kamera, bricht sie den Plattengriff nicht mehr ab; Esc tut es weiterhin.", "Gdy prawy przycisk przejmie kamera, przestaje anulować chwyt płyty; Esc nadal anuluje." } },
		{ "controls.invert_wheel", new string[5] { "Инверсия колеса", "Invert wheel", "", "Mausrad umkehren", "Odwróć kółko" } },
		{ "controls.invert_wheel_hint", new string[5] { "Только приближение. Поворот декали и размер кисти знак не меняют.", "Zoom only. Decal rotation and brush size keep their direction.", "", "Nur der Zoom. Decal-Drehung und Pinselgröße behalten ihre Richtung.", "Tylko powiększenie. Obrót kalkomanii i rozmiar pędzla nie zmieniają kierunku." } },
		{ "controls.act.frame", new string[5] { "Кадрировать", "Frame view", "", "Ansicht einpassen", "Wykadruj widok" } },
		{ "controls.act.frame_hint", new string[5] { "Камера переходит на место удара, а если показа не было — на выделенное.", "The camera moves to the impact point, or to the selection when nothing was played.", "", "Die Kamera springt zum Trefferpunkt, sonst zur Auswahl.", "Kamera przechodzi do punktu trafienia, a bez odtworzenia - do zaznaczenia." } },
		{ "controls.act.section", new string[5] { "Разрез: включить и выключить", "Section view on and off", "", "Schnittansicht ein und aus", "Przekrój włącz i wyłącz" } },
		{ "controls.act.section_hint", new string[5] { "Секущая плоскость вдоль оси выстрела: видно канал, кратер и органы фигуры.", "A cutting plane along the shot axis: the channel, the crater and the figure organs become visible.", "", "Schnittebene entlang der Schussachse: Kanal, Krater und Organe der Figur werden sichtbar.", "Płaszczyzna tnąca wzdłuż osi strzału: widać kanał, krater i organy figury." } },
		{ "controls.act.reface", new string[5] { "Развернуть разрез к камере", "Turn the section to the camera", "", "Schnitt zur Kamera drehen", "Obróć przekrój do kamery" } },
		{ "controls.act.reface_hint", new string[5] { "Плоскость сама за камерой не ходит — азимут переснимается по нажатию.", "The plane does not follow the camera by itself - the azimuth is re-taken on this key.", "", "Die Ebene folgt der Kamera nicht von selbst - der Azimut wird auf Tastendruck neu genommen.", "Płaszczyzna nie podąża za kamerą - azymut jest pobierany na to naciśnięcie." } },
		{ "controls.act.organs", new string[5] { "Внутренняя геометрия фигуры экипажа", "Crew figure internals", "", "Inneres der Besatzungsfigur", "Wnętrze figury załogi" } },
		{ "controls.act.organs_hint", new string[5] { "То же, что галка в настройках вида. При включённом разрезе органы видны и без неё.", "The same switch as in the display settings. With the section on, the organs show anyway.", "", "Derselbe Schalter wie in den Darstellungseinstellungen. Bei aktivem Schnitt sind die Organe ohnehin sichtbar.", "Ten sam przełącznik co w ustawieniach wyglądu. Przy włączonym przekroju organy i tak widać." } },
		{ "controls.act.grab", new string[5] { "Захват выделенного", "Grab the selection", "", "Auswahl greifen", "Chwyć zaznaczenie" } },
		{ "controls.act.grab_hint", new string[5] { "Дальше двигает мышь или вписанное число; Enter — применить, Esc — отменить.", "The mouse or a typed number moves it on; Enter applies, Esc cancels.", "", "Weiter bewegt die Maus oder eine eingetippte Zahl; Enter übernimmt, Esc bricht ab.", "Dalej przesuwa mysz albo wpisana liczba; Enter zatwierdza, Esc anuluje." } },
		{ "controls.act.axis_x", new string[5] { "Захват: только по оси X", "Grab: X axis only", "", "Griff: nur X-Achse", "Chwyt: tylko oś X" } },
		{ "controls.act.axis_y", new string[5] { "Захват: только по оси Y", "Grab: Y axis only", "", "Griff: nur Y-Achse", "Chwyt: tylko oś Y" } },
		{ "controls.act.axis_z", new string[5] { "Захват: только по оси Z", "Grab: Z axis only", "", "Griff: nur Z-Achse", "Chwyt: tylko oś Z" } },
		{ "controls.act.axis_hint", new string[5] { "Повторное нажатие снимает ограничение. Любая смена оси возвращает плиту в исходную точку.", "Pressing it again drops the constraint. Any axis change returns the plate to its start point.", "", "Erneutes Drücken hebt die Einschränkung auf. Jeder Achsenwechsel setzt die Platte auf den Startpunkt zurück.", "Ponowne naciśnięcie zdejmuje ograniczenie. Każda zmiana osi cofa płytę do punktu wyjścia." } },
		{ "controls.act.duplicate", new string[5] { "Копировать выделенные плиты (Ctrl+Shift+клавиша)", "Duplicate the selected plates (Ctrl+Shift+key)", "", "Ausgewählte Platten kopieren (Strg+Shift+Taste)", "Kopiuj zaznaczone płyty (Ctrl+Shift+klawisz)" } },
		{ "controls.act.duplicate_hint", new string[5] { "Ctrl и Shift зашиты намеренно: копирование необратимо, и одним пальцем его позвать нельзя.", "Ctrl and Shift are deliberately fixed: duplication cannot be undone, so one finger must not trigger it.", "", "Strg und Shift sind bewusst fest: Kopieren lässt sich nicht rückgängig machen und darf nicht mit einem Finger ausgelöst werden.", "Ctrl i Shift są celowo stałe: kopiowania nie da się cofnąć, więc jeden palec nie może go wywołać." } },
		{ "controls.mod.pan", new string[5] { "Сдвиг камеры", "Pan the camera", "", "Kamera verschieben", "Przesuń kamerę" } },
		{ "controls.mod.pan_hint", new string[5] { "Держать вместе с кнопкой вращения.", "Hold together with the orbit button.", "", "Zusammen mit der Dreh-Taste halten.", "Trzymać razem z przyciskiem obrotu." } },
		{ "controls.mod.select_add", new string[5] { "Добавить к выделению", "Add to the selection", "", "Zur Auswahl hinzufügen", "Dodaj do zaznaczenia" } },
		{ "controls.mod.select_add_hint", new string[5] { "Держать при щелчке по плите — иначе щелчок заменяет выделение целиком.", "Hold while clicking a plate - otherwise the click replaces the whole selection.", "", "Beim Klick auf eine Platte halten - sonst ersetzt der Klick die ganze Auswahl.", "Trzymać przy kliknięciu płyty - inaczej kliknięcie zastąpi całe zaznaczenie." } },
		{ "controls.mod.snap", new string[5] { "Шаг 10 мм", "10 mm steps", "", "10-mm-Schritte", "Krok 10 mm" } },
		{ "controls.mod.snap_hint", new string[5] { "Держать при перетаскивании плиты — смещение защёлкивается на кратные 10 мм.", "Hold while dragging a plate - the offset snaps to multiples of 10 mm.", "", "Beim Ziehen einer Platte halten - der Versatz rastet auf Vielfache von 10 mm ein.", "Trzymać przy przeciąganiu płyty - przesunięcie zatrzaskuje się na wielokrotnościach 10 mm." } },
		{ "controls.mod.brush", new string[5] { "Размер кисти или декали", "Brush or decal size", "", "Pinsel- oder Decal-Größe", "Rozmiar pędzla lub kalkomanii" } },
		{ "controls.mod.brush_hint", new string[5] { "Держать и крутить колесо над полотном.", "Hold and turn the wheel over the canvas.", "", "Halten und das Mausrad über der Fläche drehen.", "Trzymać i kręcić kółkiem nad płótnem." } },
		{ "controls.mod.precise", new string[5] { "Точный шаг поворота 1 градус", "Fine rotation step of 1 degree", "", "Feiner Drehschritt von 1 Grad", "Dokładny krok obrotu 1 stopień" } },
		{ "controls.mod.precise_hint", new string[5] { "Без него колесо вертит шагом 15° с защёлкой на кратные.", "Without it the wheel turns in 15 degree steps snapped to multiples.", "", "Ohne ihn dreht das Rad in 15-Grad-Schritten, eingerastet auf Vielfache.", "Bez niego kółko obraca krokiem 15 stopni z zatrzaskiem na wielokrotnościach." } },
