		{ "controls.g3.select_add", new string[5] { "Добавить плиту к выделению", "Add a plate to the selection", "", "Platte zur Auswahl hinzufügen", "Dodaj płytę do zaznaczenia" } },
		{ "controls.g3.drag", new string[5] { "Перетащить выделенное", "Drag the selection", "", "Auswahl ziehen", "Przeciągnij zaznaczenie" } },
		{ "controls.g3.orbit", new string[5] { "Вращать камеру", "Orbit the camera", "", "Kamera drehen", "Obracaj kamerę" } },
		{ "controls.g3.pan", new string[5] { "Сдвинуть камеру", "Pan the camera", "", "Kamera verschieben", "Przesuń kamerę" } },
