		{ "controls.g2.point", new string[5] { "Вершина контура, декаль, штамп кисти", "Outline vertex, decal, brush stamp", "", "Umrisspunkt, Decal, Pinselstempel", "Wierzchołek konturu, kalkomania, stempel pędzla" } },
		{ "controls.g2.paint", new string[5] { "Мазок кисти: зажать и вести", "Brush stroke: hold and drag", "", "Pinselstrich: halten und ziehen", "Pociągnięcie pędzla: przytrzymaj i prowadź" } },
		{ "controls.g2.pan", new string[5] { "Сдвинуть полотно: зажать и вести", "Pan the canvas: hold and drag", "", "Fläche verschieben: halten und ziehen", "Przesuń płótno: przytrzymaj i prowadź" } },
		{ "controls.g2.zoom", new string[5] { "Приблизить и отдалить", "Zoom in and out", "", "Heran- und wegzoomen", "Przybliż i oddal" } },
		{ "controls.g2.rotate", new string[5] { "Повернуть декаль в руке или выбранную фигуру", "Rotate the held decal or the selected shape", "", "Gehaltenes Decal oder gewählte Figur drehen", "Obróć trzymaną kalkomanię lub wybraną figurę" } },
		{ "controls.g2.menu", new string[5] { "Меню", "Menu", "", "Menü", "Menu" } },
		{ "common.version", new string[5] { "версия", "version", "версия", "Version", "wersja" } },
		{ "sandbox.fire", new string[5] { "ОГОНЬ", "FIRE", "УТ", "FEUER", "OGIEŃ" } },
		{ "sandbox.solve_super", new string[5] { "РАССЧИТАТЬ", "SOLVE", "ИСӘПЛӘҮ", "BERECHNEN", "OBLICZ" } },
		{ "super.refuse.no_plates", new string[5] { "Перед снарядом нет плит — считать нечего.", "No plates in front of the projectile — nothing to solve.", "Снаряд алдында пластина юк — исәпләргә берни юк.", "Keine Platten vor dem Geschoss — nichts zu berechnen.", "Brak płyt przed pociskiem — nie ma czego liczyć." } },
		{ "super.refuse.non_plate", new string[5] { "В сцене есть объект, который этот режим не описывает: оставьте только плиты.", "The scene contains an object this mode cannot describe: leave plates only.", "Сәхнәдә бу режим тасвирламый торган объект бар: пластиналарны гына калдырыгыз.", "Die Szene enthält ein Objekt, das dieser Modus nicht beschreibt: nur Platten belassen.", "Scena zawiera obiekt, którego ten tryb nie opisuje: zostaw same płyty." } },
		{ "super.refuse.material.no_row", new string[5] { "Строки реестра Super для вещества «{0}» нет: нужны измеренные константы — плотность, течение, разрушение, ударная адиабата. Подставлять похожее вещество под этим именем режим не станет.", "The Super registry has no row for “{0}”: measured constants are needed — density, flow, failure, Hugoniot. This mode will not put a similar substance under that name.", "Super реестрында «{0}» матдәсе өчен юл юк: үлчәнгән даимилекләр кирәк — тыгызлык, агым, җимерелү, удар адиабатасы. Бу режим шул исем астына охшаш матдәне куймый.", "Das Super-Register hat keine Zeile für „{0}“: gemessene Konstanten fehlen — Dichte, Fließen, Versagen, Hugoniot. Dieser Modus setzt keinen ähnlichen Werkstoff unter diesen Namen.", "Rejestr Super nie ma wiersza dla „{0}”: potrzebne są zmierzone stałe — gęstość, płynięcie, zniszczenie, adiabata uderzeniowa. Ten tryb nie podstawi podobnego materiału pod tę nazwę." } },
		{ "super.refuse.material.needs_model", new string[5] { "Веществу «{0}» нужна другая модель прочности — семейства Джонсона-Хольмквиста: оно хрупкое, колется, а не течёт, и прочность зависит от давления. Строка Джонсона-Кука этого не выражает: не хватает модели, а не чисел.", "“{0}” needs a different strength model — the Johnson-Holmquist family: it is brittle, it shatters instead of flowing, and its strength depends on pressure. A Johnson-Cook row cannot express that: a model is missing, not numbers.", "«{0}» матдәсенә башка ныклык моделе кирәк — Johnson-Holmquist гаиләсе: ул сынучан, акмый, ә ватыла, ныклыгы басымга бәйле. Johnson-Cook юлы моны әйтә алмый: модель җитми, саннар түгел.", "„{0}“ braucht ein anderes Festigkeitsmodell — die Johnson-Holmquist-Familie: spröde, es zerspringt statt zu fließen, und die Festigkeit hängt vom Druck ab. Eine Johnson-Cook-Zeile kann das nicht ausdrücken: es fehlt ein Modell, nicht Zahlen.", "„{0}” wymaga innego modelu wytrzymałości — rodziny Johnson-Holmquist: jest kruchy, pęka zamiast płynąć, a wytrzymałość zależy od ciśnienia. Wiersz Johnson-Cook tego nie wyraża: brakuje modelu, nie liczb." } },
		{ "super.refuse.material.needs_j3", new string[5] { "Высокотвёрдой броне «{0}» нужна поверхность текучести с третьим инвариантом (угол Лоде): прочность на растяжение и на сжатие у неё разная, а критерий Мизеса, которым считает этот режим, такого различия не выражает. Не хватает модели, а не чисел.", "High-hardness armour “{0}” needs a yield surface with the third invariant (the Lode angle): its tensile and compressive strengths differ, and the von Mises criterion this mode uses cannot express that difference. A model is missing, not numbers.", "«{0}» югары катылыктагы бронясына өченче инвариантлы (Лоде почмагы) агучанлык өслеге кирәк: сузуга һәм кысуга ныклыгы төрле, ә бу режим исәпли торган Мизес критерие бу аерманы әйтә алмый. Модель җитми, саннар түгел.", "Hochhartes Panzermaterial „{0}“ braucht eine Fließfläche mit der dritten Invariante (Lode-Winkel): Zug- und Druckfestigkeit unterscheiden sich, und das von-Mises-Kriterium dieses Modus kann diesen Unterschied nicht ausdrücken. Es fehlt ein Modell, nicht Zahlen.", "Pancerz o wysokiej twardości „{0}” wymaga powierzchni plastyczności z trzecim niezmiennikiem (kąt Lodego): wytrzymałość na rozciąganie i na ściskanie jest różna, a kryterium von Misesa, którym liczy ten tryb, nie wyraża tej różnicy. Brakuje modelu, nie liczb." } },
		{ "super.refuse.material.anisotropic", new string[5] { "«{0}» — слоистый композит: он разрушается расслоением по границам слоёв, а этот режим считает сплошную однородную среду, у которой таких границ нет вовсе. Здесь модель НЕПРИМЕНИМА, а не просто неточна.", "“{0}” is a layered composite: it fails by delamination along the layer boundaries, while this mode solves a continuous homogeneous medium that has no such boundaries at all. Here the model is INAPPLICABLE, not merely inaccurate.", "«{0}» — катламлы композит: ул катлам чикләре буйлап аерылып җимерелә, ә бу режим андый чикләре бөтенләй булмаган тоташ бертөрле мохитне исәпли. Монда модельне КУЛЛАНЫП БУЛМЫЙ — мәсьәлә аның төгәллегендә түгел.", "„{0}“ ist ein Schichtverbund: er versagt durch Delamination entlang der Schichtgrenzen, während dieser Modus ein kontinuierliches homogenes Medium rechnet, das solche Grenzen gar nicht hat. Hier ist das Modell UNANWENDBAR, nicht bloß ungenau.", "„{0}” to kompozyt warstwowy: niszczy się przez rozwarstwienie wzdłuż granic warstw, a ten tryb liczy ciągły ośrodek jednorodny, który takich granic w ogóle nie ma. Tutaj model jest NIESTOSOWALNY, a nie po prostu niedokładny." } },
		{ "super.refuse.material.not_accepted", new string[5] { "Строка реестра для вещества «{0}» есть, но её приёмка не пройдена: исход по диапазону множителя деформации разрушения оказался немонотонным, и значение проката лежит внутри этого диапазона. Пока это так, строка отгружалась бы как правдоподобная, а не как проверенная. Вернётся после фазы разброса прочности, той же приёмкой.", "The registry does have a row for “{0}”, but its acceptance has not passed: the outcome across the failure-strain multiplier band came out non-monotonic, and the rolled-plate value lies inside that band. While that holds, shipping the row would ship something plausible rather than something checked. It returns after the strength-scatter phase, through the same acceptance.", "«{0}» матдәсе өчен реестр юлы бар, ләкин аның кабул итүе үтмәде: җимерелү деформациясе тапкырлавы диапазоны буенча нәтиҗә монотон булмады, ә прокат кыйммәте шул диапазон эчендә ята. Шулай булганда юл тикшерелгән түгел, ә ышандыргыч кына булып чыга. Ныклык таралышы фазасыннан соң шул ук кабул итү белән кайтачак.", "Für „{0}“ gibt es durchaus eine Registerzeile, aber ihre Abnahme ist nicht bestanden: das Ergebnis über das Band des Bruchdehnungs-Faktors fiel nicht monoton aus, und der Walzblech-Wert liegt innerhalb dieses Bandes. Solange das so ist, wäre die Zeile plausibel statt geprüft. Sie kehrt nach der Phase der Festigkeitsstreuung zurück, über dieselbe Abnahme.", "Rejestr ma wiersz dla „{0}”, ale jego odbiór nie został zaliczony: wynik w całym paśmie mnożnika odkształcenia niszczącego okazał się niemonotoniczny, a wartość blachy walcowanej leży wewnątrz tego pasma. Dopóki tak jest, wiersz byłby wiarygodny, a nie sprawdzony. Wróci po fazie rozrzutu wytrzymałości, tym samym odbiorem." } },
		{ "super.refuse.round", new string[5] { "Этот режим считает длинный стержень, кумулятивную струю и полое тело.", "This mode solves long rods, shaped-charge jets and hollow bodies.", "Бу режим озын таякны, кумулятив агымны һәм куыш җисемне исәпли.", "Dieser Modus berechnet Langstäbe, Hohlladungsstrahlen und Hohlkörper.", "Ten tryb liczy długie pręty, strumienie kumulacyjne i ciała drążone." } },
		{ "super.refuse.round.core_conflict", new string[5] { "Паспорт выстрела называет веществом сердечника «{0}», а сердечник каталога даёт «{1}». Два источника вещества — расчёт отказан: иначе снаряд считался бы из другого металла под своим именем.", "The round's passport names core substance “{0}”, while the catalogue core gives “{1}”. Two sources for one substance — refused: otherwise the round would be computed from a different metal under its own name.", "Выстрел паспорты сердечник матдәсе итеп «{0}» дип атый, ә каталог сердечнигы «{1}» бирә. Бер матдәгә ике чыганак — исәпләү кире кагыла: юкса снаряд үз исеме астында башка металлдан исәпләнер иде.", "Der Passeintrag des Geschosses nennt als Kernwerkstoff „{0}“, der Katalogkern liefert „{1}“. Zwei Quellen für einen Werkstoff — abgelehnt: sonst würde das Geschoss unter eigenem Namen aus einem anderen Metall gerechnet.", "Paszport pocisku podaje jako materiał rdzenia „{0}”, a rdzeń z katalogu daje „{1}”. Dwa źródła jednego materiału — odmowa: inaczej pocisk liczony byłby z innego metalu pod własną nazwą." } },
		{ "super.refuse.jet_grid", new string[5] { "Шаг частиц не разрешает струю: нужно не меньше четырёх ячеек поперёк её диаметра. Нажмите «Шаг под струю» в панели Super.", "The particle spacing cannot resolve the jet: at least four cells across its diameter are required. Press “Spacing for jet” in the Super panel.", "Кисәкчә адымы агымны аера алмый: аның диаметры аша кимендә дүрт күзәнәк кирәк. Super панелендә «Агым өчен адым» төймәсен басыгыз.", "Der Partikelabstand kann den Strahl nicht auflösen: mindestens vier Zellen über seinen Durchmesser sind nötig. Im Super-Panel „Abstand für Strahl“ drücken.", "Krok cząstek nie rozdziela strumienia: potrzeba co najmniej czterech komórek na jego średnicy. Naciśnij „Krok pod strumień” w panelu Super." } },
		{ "super.refuse.jet_too_fine", new string[5] { "Струя этого заряда тоньше, чем режим умеет считать: нужный шаг мельче предела панели. Настройки, которая это исправит, нет — возьмите заряд крупнее.", "This charge's jet is finer than the mode can resolve: the required spacing is below the panel's limit. No setting fixes this — use a larger charge.", "Бу корылманың агымы режим исәпли алганнан нечкәрәк: кирәкле адым панель чигеннән кечерәк. Моны төзәтүче көйләү юк — эрерәк корылма алыгыз.", "Der Strahl dieser Ladung ist feiner als der Modus auflösen kann: der nötige Abstand liegt unter dem Panel-Limit. Keine Einstellung hilft — größere Ladung wählen.", "Strumień tego ładunku jest cieńszy, niż tryb potrafi rozdzielić: wymagany krok jest poniżej limitu panelu. Żadne ustawienie tego nie naprawi — użyj większego ładunku." } },
		{ "super.refuse.too_big", new string[5] { "Сцене нужно {0:F1} млн частиц при шаге {1:F2} мм, а видеопамять этой машины вмещает {2:F1} млн. Влезет при шаге не мельче {3:F2} мм (кнопка «Шаг под бюджет» ставит {4:F2} мм) — или уменьшите плиты.", "The scene needs {0:F1} M particles at {1:F2} mm spacing, but this machine's video memory holds {2:F1} M. It fits at a spacing of at least {3:F2} mm (the \"Spacing for budget\" button sets {4:F2} mm) — or use smaller plates.", "Сәхнәгә {1:F2} мм адымда {0:F1} млн кисәкчә кирәк, ә бу машинаның видеохәтере {2:F1} млн сыйдыра. Адым {3:F2} мм дан ким булмаганда сыя («Бюджетка адым» төймәсе {4:F2} мм куя) — яки пластиналарны кечерәйтегез.", "Die Szene braucht bei {1:F2} mm Abstand {0:F1} Mio. Partikel, der Grafikspeicher dieser Maschine fasst {2:F1} Mio. Sie passt ab {3:F2} mm Abstand (die Schaltfläche \"Abstand fürs Budget\" setzt {4:F2} mm) — oder kleinere Platten verwenden.", "Scena potrzebuje {0:F1} mln cząstek przy odstępie {1:F2} mm, a pamięć wideo tej maszyny mieści {2:F1} mln. Zmieści się przy odstępie co najmniej {3:F2} mm (przycisk \"Odstęp pod budżet\" ustawia {4:F2} mm) — albo zmniejsz płyty." } },
		{ "super.refuse.busy", new string[5] { "Расчёт уже идёт.", "A solve is already running.", "Исәпләү инде бара.", "Eine Berechnung läuft bereits.", "Obliczenia już trwają." } },
		{ "super.era.refuse.gap_unresolved", new string[5] { "Зазор ВВ кассеты «{0}» ({1} мм) сетка не разрешает: пластины оказались бы в одном узле переноса. Нужен шаг частиц мельче {2} мм.", "The explosive gap of cassette “{0}” ({1} mm) is not resolved by the grid: the plates would share a transfer node. Particle spacing finer than {2} mm is required.", "«{0}» кассетасының ШМ ярыгын ({1} мм) челтәр аермый: пластиналар бер күчерү төенендә булыр иде. {2} мм-дан нечкәрәк кисәкчә адымы кирәк.", "Der Sprengstoffspalt der Kassette „{0}“ ({1} mm) wird vom Gitter nicht aufgelöst: die Platten teilten sich einen Übertragungsknoten. Partikelabstand feiner als {2} mm nötig.", "Szczelina MW kasety „{0}” ({1} mm) nie jest rozdzielana przez siatkę: płyty trafiłyby do jednego węzła przeniesienia. Potrzebny krok cząstek drobniejszy niż {2} mm." } },
		{ "super.era.refuse.thickness_quantised", new string[5] { "Метаемая пластина {0} мм при шаге {1} мм запекается в {2} мм — удельный импульс сдвинут на {3}: нужен шаг мельче.", "The flyer plate {0} mm at spacing {1} mm bakes to {2} mm — specific impulse shifted by {3}: finer spacing required.", "{0} мм очучы пластина {1} мм адымда {2} мм булып пешә — чагыштырма импульс {3} күчкән: нечкәрәк адым кирәк.", "Die Wurfplatte {0} mm wird bei Abstand {1} mm zu {2} mm gebacken — spezifischer Impuls um {3} verschoben: feinerer Abstand nötig.", "Płyta miotana {0} mm przy kroku {1} mm zapieka się do {2} mm — impuls właściwy przesunięty o {3}: potrzebny drobniejszy krok." } },
		{ "super.era.refuse.material", new string[5] { "Вещество метаемой пластины «{0}» реестру Super неизвестно.", "Flyer plate material “{0}” is unknown to the Super registry.", "Очучы пластина матдәсе «{0}» Super реестрына билгесез.", "Werkstoff der Wurfplatte „{0}“ ist dem Super-Register unbekannt.", "Materiał płyty miotanej „{0}” jest nieznany rejestrowi Super." } },
		{ "super.era.refuse.tilt", new string[5] { "Кассета наклонена на {0}° — почти вдоль выстрела, раскладка по нормали вырождается.", "The cassette is tilted {0}° — nearly along the shot line, the normal layout degenerates.", "Кассета {0}° авышкан — ату сызыгы буйлап диярлек, норма буенча урнаштыру таркала.", "Die Kassette ist um {0}° geneigt — fast entlang der Schusslinie, die Normalenanordnung entartet.", "Kaseta pochylona o {0}° — niemal wzdłuż linii strzału, układ wzdłuż normalnej degeneruje się." } },
		{ "super.nera.refuse.tilt", new string[5] { "Пакет наклонён на {0}° — почти вдоль выстрела, раскладка по нормали вырождается.", "The pack is tilted {0}° — nearly along the shot line, the normal layout degenerates.", "Пакет {0}° авышкан — ату сызыгы буйлап диярлек, норма буенча урнаштыру таркала.", "Das Paket ist um {0}° geneigt — fast entlang der Schusslinie, die Normalenanordnung entartet.", "Pakiet pochylony o {0}° — niemal wzdłuż linii strzału, układ wzdłuż normalnej degeneruje się." } },
		{ "super.refuse.reactive_last", new string[5] { "Последней по ходу выстрела стоит реактивная защита: за ней должна быть плита брони — исход судится по ней.", "The last object along the shot is reactive armour: an armour plate must stand behind it — the outcome is judged on that plate.", "Ату юлында соңгы объект — реактив саклану: аның артында броня пластинасы булырга тиеш, нәтиҗә аның буенча билгеләнә.", "Das letzte Objekt entlang des Schusses ist Reaktivpanzerung: dahinter muss eine Panzerplatte stehen — das Ergebnis wird an ihr beurteilt.", "Ostatnim obiektem na linii strzału jest pancerz reaktywny: za nim musi stać płyta pancerza — wynik ocenia się po niej." } },
		{ "super.refuse.tandem", new string[5] { "Тандемный заряд этот режим не считает: предзаряд не моделируется, а струя основного заряда была бы моноблоком под чужим именем.", "This mode does not solve tandem charges: the precursor is not modelled, and the main jet would be a single charge under a different name.", "Бу режим тандем корылмасын исәпләми: алдан корылма модельләштерелми, ә төп корылма агымы чит исем астындагы моноблок булыр иде.", "Dieser Modus berechnet keine Tandemladungen: die Vorladung wird nicht modelliert, und der Hauptstrahl wäre eine Einzelladung unter fremdem Namen.", "Ten tryb nie liczy ładunków tandemowych: ładunek wstępny nie jest modelowany, a strumień główny byłby monoblokiem pod cudzą nazwą." } },
		{ "super.nera.refuse.unbonded", new string[5] { "Пакет «{0}» с несвязанными пластинами: этот решатель сваривает соприкасающиеся тела, скользящего контакта у него нет.", "Pack “{0}” has unbonded plates: this solver welds touching bodies, it has no sliding contact.", "«{0}» пакетының пластиналары бәйләнмәгән: бу чишүче тиешкән җисемнәрне эретеп ябыштыра, шуышма контакты юк.", "Paket „{0}“ hat ungebundene Platten: dieser Löser verschweißt sich berührende Körper, er kennt keinen Gleitkontakt.", "Pakiet „{0}” ma niezwiązane płyty: ten solver spawa stykające się ciała, nie ma kontaktu ślizgowego." } },
		{ "super.nera.refuse.quantised", new string[5] { "Слои пакета «{0}» ({1} мм) при шаге {2} мм не укладываются в целое число частиц (ошибка толщины больше 10 %): нужен шаг не крупнее {3} мм.", "The layers of pack “{0}” ({1} mm) do not fit whole particles at spacing {2} mm (thickness error above 10 %): spacing of {3} mm or finer is required.", "«{0}» пакетының катламнары ({1} мм) {2} мм адымда бөтен кисәкчәләргә сыймый (калынлык хатасы 10 %-тан зуррак): {3} мм-дан эре булмаган адым кирәк.", "Die Schichten des Pakets „{0}“ ({1} mm) passen bei Abstand {2} mm nicht in ganze Partikel (Dickenfehler über 10 %): Abstand {3} mm oder feiner nötig.", "Warstwy pakietu „{0}” ({1} mm) nie mieszczą się w całych cząstkach przy kroku {2} mm (błąd grubości ponad 10 %): potrzebny krok nie większy niż {3} mm." } },
		{ "super.nera.refuse.thin", new string[5] { "Пластина пакета {0} мм при шаге {1} мм — всего {2} слоя частиц, а выпучивание требует не меньше четырёх: нужен шаг не крупнее {3} мм.", "Pack plate {0} mm at spacing {1} mm is only {2} particle layers thick, and bulging needs at least four: spacing of {3} mm or finer is required.", "{1} мм адымда {0} мм пакет пластинасы — нибары {2} кисәкчә катламы, ә кабару кимендә дүртне таләп итә: {3} мм-дан эре булмаган адым кирәк.", "Paketplatte {0} mm bei Abstand {1} mm ist nur {2} Partikelschichten dick, Ausbeulen braucht mindestens vier: Abstand {3} mm oder feiner nötig.", "Płyta pakietu {0} mm przy kroku {1} mm ma tylko {2} warstwy cząstek, a wybrzuszenie wymaga co najmniej czterech: potrzebny krok nie większy niż {3} mm." } },
		{ "super.avail.prefix", new string[5] { "Super откажет: ", "Super will refuse: ", "Super баш тартачак: ", "Super lehnt ab: ", "Super odmówi: " } },
		{ "super.refuse.mixed_tilt", new string[5] { "Плиты наклонены вокруг разных осей: «{0}» уходит от общей оси наклона на {1}°. Этот режим кладёт все плиты наклоном вокруг одной оси.", "Plates are tilted about different axes: “{0}” departs from the common tilt axis by {1}°. This mode lays all plates tilted about one axis.", "Пластиналар төрле күчәрләр тирәсендә авышкан: «{0}» уртак авышу күчәреннән {1}° читкә китә. Бу режим бар пластиналарны бер күчәр тирәсендә авыштырып куя.", "Platten sind um verschiedene Achsen geneigt: „{0}“ weicht {1}° von der gemeinsamen Neigungsachse ab. Dieser Modus legt alle Platten um eine Achse geneigt.", "Płyty są pochylone wokół różnych osi: „{0}” odbiega od wspólnej osi pochylenia o {1}°. Ten tryb układa wszystkie płyty pochylone wokół jednej osi." } },
		{ "super.refuse.off_axis", new string[5] { "«{0}» стоит в {1} мм от линии выстрела (допуск {2} мм): этот режим кладёт тела по оси. Поставьте объект на линию.", "“{0}” stands {1} mm off the shot line (tolerance {2} mm): this mode lays bodies on the axis. Put the object on the line.", "«{0}» ату сызыгыннан {1} мм читтә тора (рөхсәт {2} мм): бу режим җисемнәрне күчәр буенча куя. Объектны сызыкка куегыз.", "„{0}“ steht {1} mm neben der Schusslinie (Toleranz {2} mm): dieser Modus legt Körper auf die Achse. Objekt auf die Linie setzen.", "„{0}” stoi {1} mm od linii strzału (tolerancja {2} mm): ten tryb układa ciała na osi. Ustaw obiekt na linii." } },
		{ "super.refuse.no_line", new string[5] { "Линия выстрела не задевает ни одного тела — считать нечего. Поставьте хотя бы одну плиту на пути снаряда.", "The shot line does not touch any body — there is nothing to compute. Put at least one plate in the projectile's path.", "Ату сызыгы бер җисемгә дә кагылмый — исәпләргә нәрсә дә юк. Снаряд юлына ким дигәндә бер плита куегыз.", "Die Schusslinie trifft keinen Körper — es gibt nichts zu rechnen. Stellen Sie mindestens eine Platte in die Flugbahn.", "Linia strzału nie trafia w żadne ciało — nie ma czego liczyć. Postaw co najmniej jedną płytę na drodze pocisku." } },
		{ "super.refuse.bodies_overlap", new string[5] { "{0} и {1} заходят друг в друга на {2} мм (допуск — полшага частиц): два вещества в одном объёме не сцена. Раздвиньте тела.", "{0} and {1} overlap by {2} mm (tolerance: half a particle spacing): two materials in one volume are not a scene. Move the bodies apart.", "{0} һәм {1} бер-берсенә {2} мм керә (рөхсәт — кисәкчәләр адымының яртысы): бер күләмдәге ике матдә — сәхнә түгел. Җисемнәрне аерыгыз.", "{0} und {1} überlappen um {2} mm (Toleranz: halber Partikelabstand): zwei Stoffe in einem Volumen sind keine Szene. Körper auseinanderrücken.", "{0} i {1} nachodzą na siebie o {2} mm (tolerancja — pół kroku cząstek): dwa materiały w jednej objętości to nie scena. Rozsuń ciała." } },
		{ "super.passport.bonded", new string[5] { "{0} и {1} сцеплены: просвет {2:F1} мм меньше трёх ячеек сетки ({3:F1} мм) — без проскальзывания и отрыва, пока вещество не разрушится", "{0} and {1} are bonded: clearance {2:F1} mm is less than three grid cells ({3:F1} mm) — no sliding and no separation until the material fails", "{0} һәм {1} тоташтырылган: ачыклык {2:F1} мм челтәрнең өч күзәнәгеннән ({3:F1} мм) кимрәк — матдә җимерелгәнче шуу да, аерылу да юк", "{0} und {1} sind verbunden: Abstand {2:F1} mm ist kleiner als drei Gitterzellen ({3:F1} mm) — kein Gleiten und kein Ablösen, bis der Werkstoff versagt", "{0} i {1} są sczepione: prześwit {2:F1} mm jest mniejszy niż trzy komórki siatki ({3:F1} mm) — bez poślizgu i oderwania, dopóki materiał się nie zniszczy" } },
		{ "super.passport.bonded_hint", new string[5] { "шаг частиц мельче {0:F2} мм разрешит этот зазор", "a particle spacing finer than {0:F2} mm will resolve this gap", "{0:F2} мм-дан вагырак кисәкчәләр адымы бу аралыкны аерачак", "ein Partikelabstand feiner als {0:F2} mm löst diesen Spalt auf", "krok cząstek mniejszy niż {0:F2} mm rozdzieli tę szczelinę" } },
		{ "super.passport.bonded_flyer", new string[5] { "{0} сцеплена с бронёй и метаться не будет", "{0} is bonded to the armour and will not be thrown", "{0} бронята тоташтырылган һәм ыргытылмаячак", "{0} ist mit der Panzerung verbunden und wird nicht geworfen", "{0} jest sczepiona z pancerzem i nie zostanie wyrzucona" } },
		{ "super.passport.bystander", new string[5] { "«{0}» не на линии выстрела: запечено и может поймать обломки, но это не первое касание, не мишень и не судья", "“{0}” is off the shot line: it is baked and may catch debris, but it is not the first contact, the target or the judge", "«{0}» ату сызыгында түгел: пешерелгән һәм кыйпылчыкларны тотарга мөмкин, ләкин ул беренче кагылу да, максат та, хөкемче дә түгел", "„{0}“ steht nicht auf der Schusslinie: gebacken und kann Trümmer auffangen, ist aber weder Erstkontakt noch Ziel noch Richter", "„{0}” nie leży na linii strzału: jest wypiekane i może złapać odłamki, ale nie jest pierwszym kontaktem, celem ani sędzią" } },
		{ "super.passport.bystander_inert", new string[5] { "кассета «{0}» в стороне от линии выстрела — привод не взводится, метаемые пластины инертны", "cassette “{0}” is off the shot line — its drive is not armed, the flyer plates are inert", "«{0}» кассетасы ату сызыгыннан читтә — йөртмә коралланмый, ыргытылучы пластиналар инерт", "Kassette „{0}“ steht neben der Schusslinie — der Antrieb wird nicht scharfgemacht, die Wurfplatten sind inert", "kaseta „{0}” leży obok linii strzału — napęd nie jest uzbrajany, płyty miotane są bierne" } },
		{ "super.passport.pose", new string[5] { "«{0}» запечена как построена: наклон {1:F1}°, снос {2:F0} мм от линии выстрела, {3:F0}×{4:F0} мм", "“{0}” is baked as built: obliquity {1:F1}°, {2:F0} mm off the shot line, {3:F0}×{4:F0} mm", "«{0}» төзелгәнчә пешерелгән: авышлык {1:F1}°, ату сызыгыннан {2:F0} мм читтә, {3:F0}×{4:F0} мм", "„{0}“ wird wie gebaut gebacken: Schräge {1:F1}°, {2:F0} mm neben der Schusslinie, {3:F0}×{4:F0} mm", "„{0}” jest wypiekana tak, jak zbudowana: nachylenie {1:F1}°, {2:F0} mm od linii strzału, {3:F0}×{4:F0} mm" } },
		{ "super.hud.duration_ceiling", new string[5] { "Верх ручки 10 мс — окно практически без потолка: длинному стержню нужно около миллисекунды. После ≈600 мкс сильно деформированные частицы могут вырождаться — сторожа прогона назовут отказ по имени.", "Slider top is 10 ms — the window is practically unlimited: a long rod needs about a millisecond. Beyond ≈600 us heavily deformed particles may degenerate — the run guards will name the refusal.", "Ручка өсте 10 мс — тәрәзә чиксез диярлек: озын таякка якынча миллисекунд кирәк. ≈600 мкс тан соң нык деформацияләнгән кисәкчәләр бозылырга мөмкин — йөреш сакчылары баш тартуны исеме белән атар.", "Obergrenze des Reglers 10 ms — das Fenster ist praktisch unbegrenzt: ein langer Stab braucht etwa eine Millisekunde. Nach ≈600 us können stark verformte Partikel entarten — die Laufwächter nennen den Abbruch beim Namen.", "Górna granica suwaka 10 ms — okno praktycznie bez limitu: długi pręt potrzebuje około milisekundy. Po ≈600 us silnie odkształcone cząstki mogą się degenerować — strażnicy przebiegu nazwą odmowę po imieniu." } },
		{ "super.hud.duration_exact", new string[5] { "Точно, мкс:", "Exact, us:", "Төгәл, мкс:", "Genau, us:", "Dokładnie, us:" } },
		{ "super.hud.cost_knobs", new string[5] { "Цена: длительность — линейно; шаг частиц — в четвёртой степени (частиц в кубе, шагов по времени ещё раз). Длительность — самый дешёвый рычаг.", "Cost: duration scales linearly; particle spacing to the fourth power (particles cubically, time steps once more). Duration is the cheapest knob.", "Бәя: озынлык — сызыкча; кисәкчә адымы — дүртенче дәрәҗәдә (кисәкчәләр кубта, вакыт адымнары тагын бер тапкыр). Озынлык — иң арзан рычаг.", "Kosten: Dauer linear; Partikelabstand in vierter Potenz (Partikel kubisch, Zeitschritte noch einmal). Die Dauer ist der billigste Regler.", "Koszt: czas trwania liniowo; krok cząstek w czwartej potędze (cząstki sześciennie, kroki czasowe jeszcze raz). Czas trwania to najtańsza dźwignia." } },
