		{ "material.titaniumdiboride", new string[5] { "Диборид титана TiB2", "Titanium diboride TiB2", "", "Titandiborid TiB2", "Dwuborek tytanu TiB2" } },
		{ "material.depleteduraniumarmour", new string[5] { "Обеднённый уран", "Depleted uranium", "", "Abgereichertes Uran", "Uran zubozony" } },
		{ "material.alumina", new string[5] { "Оксид алюминия", "Alumina AD995", "", "Aluminiumoxid AD995", "Tlenek glinu AD995" } },
		{ "material.rhasetb", new string[5] { "RHA (набор Б)", "RHA (set B)", "", "RHA (Satz B)", "RHA (zestaw B)" } },
		{ "material.steel4340", new string[5] { "Сталь 4340", "4340 steel", "", "Stahl 4340", "Stal 4340" } },
		{ "material.polyurethane", new string[5] { "Полиуретан", "Polyurethane", "Полиуретан", "Polyurethan", "Poliuretan" } },
		{ "material.neoprene", new string[5] { "Неопрен", "Neoprene", "Неопрен", "Neopren", "Neopren" } },
		{ "material.naturalrubber", new string[5] { "Натуральная резина", "Natural rubber", "Табигый каучук", "Naturkautschuk", "Kauczuk naturalny" } },
		{ "material.rha.desc", new string[5] { "Катаная гомогенная броня, ro = 7850. R_t = 5.3 ГПа, подгонка по Hauver.", "Rolled homogeneous armour, rho = 7850. R_t = 5.3 GPa, fitted after Hauver.", "", "Gewalzte homogene Panzerung, rho = 7850. R_t = 5,3 GPa, angepasst nach Hauver.", "Walcowany pancerz jednorodny, rho = 7850. R_t = 5,3 GPa, dopasowanie wg Hauvera." } },
		{ "material.rhasetb.desc", new string[5] { "RHA, ВТОРОЙ набор Джонсона-Кука (Grey et al.). Это ТА ЖЕ сталь: ro = 7850, модули и ударная адиабата те же, расходятся только пять коэффициентов течения. Числа меняются ТОЛЬКО в Super - аналитическое ядро коэффициентов Джонсона-Кука не читает вовсе. Провенанс: ASSUMED_BY_SUBSTITUTION.", "RHA, the SECOND Johnson-Cook set (Grey et al.). Same steel: rho = 7850, same moduli and Hugoniot, only the five flow constants differ. The numbers change in Super ONLY - the analytic core does not read Johnson-Cook constants at all. Provenance: ASSUMED_BY_SUBSTITUTION.", "", "RHA, ZWEITER Johnson-Cook-Satz (Grey et al.). Derselbe Stahl: rho = 7850, gleiche Moduln und Hugoniot, nur die funf Fliesskonstanten unterscheiden sich. Die Zahlen andern sich NUR in Super. Provenienz: ASSUMED_BY_SUBSTITUTION.", "RHA, DRUGI zestaw Johnsona-Cooka (Grey i in.). Ta sama stal: rho = 7850, te same moduly i hugoniot, roznia sie tylko piec stalych plyniecia. Liczby zmieniaja sie TYLKO w Super. Proweniencja: ASSUMED_BY_SUBSTITUTION." } },
		{ "material.steel4340.desc", new string[5] { "Сталь 4340, ro = 7830. Единственная строка реестра Super с полным и согласованным набором: течение + повреждаемость + уравнение состояния. ВЫБИРАЕТСЯ ТОЛЬКО В SUPER: у аналитического ядра нет строки мишени (R_t) для этой стали - есть только пенетратор. Подставить R_t от RHA нельзя, вышел бы результат RHA под чужим именем.", "4340 steel, rho = 7830. The only row in the Super register with a complete, self-consistent set: flow + damage + equation of state. SUPER ONLY: the analytic core has no target row (R_t) for this steel - only a penetrator row. Substituting RHA's R_t would report an RHA result under the wrong name.", "", "Stahl 4340, rho = 7830. Die einzige Zeile im Super-Register mit vollstandigem, in sich stimmigem Satz: Fliessen + Schadigung + Zustandsgleichung. NUR IN SUPER: dem analytischen Kern fehlt die Zielzeile (R_t) fur diesen Stahl.", "Stal 4340, rho = 7830. Jedyny wiersz rejestru Super z pelnym i spojnym zestawem: plyniecie + uszkodzenia + rownanie stanu. TYLKO W SUPER: rdzen analityczny nie ma wiersza celu (R_t) dla tej stali." } },
		{ "material.caststeel.desc", new string[5] { "Литая броневая сталь, ro = 7850. R_t = 5.3 ГПа, как у RHA: коэффициент 0.85-0.9 проверен и оказался фольклором без первоисточника. Отличие литья — в разрушении (пористость, откол), а не в сопротивлении.", "Cast armour steel, rho = 7850. R_t = 5.3 GPa, same as RHA: the 0.85-0.9 ratio was checked and turned out to be folklore with no primary source. Cast differs in fracture (porosity, spall), not in resistance.", "", "", "" } },
		{ "material.hha.desc", new string[5] { "Высокотвёрдая сталь, ro = 7850. R_t = 7.0 ГПа, подгонка.", "High-hardness steel, rho = 7850. R_t = 7.0 GPa, fitted.", "", "Hochharter Stahl, rho = 7850. R_t = 7,0 GPa, angepasst.", "Stal o wysokiej twardosci, rho = 7850. R_t = 7,0 GPa, dopasowanie." } },
		{ "material.aluminum.desc", new string[5] { "Алюминиевый сплав, ro = 2700. R_t = 1.5 ГПа, подгонка.", "Aluminium alloy, rho = 2700. R_t = 1.5 GPa, fitted.", "", "Aluminiumlegierung, rho = 2700. R_t = 1,5 GPa, angepasst.", "Stop aluminium, rho = 2700. R_t = 1,5 GPa, dopasowanie." } },
		{ "material.titanium.desc", new string[5] { "Ti-6Al-4V, ro = 4430. R_t = 4.2 ГПа, подгонка.", "Ti-6Al-4V, rho = 4430. R_t = 4.2 GPa, fitted.", "", "Ti-6Al-4V, rho = 4430. R_t = 4,2 GPa, angepasst.", "Ti-6Al-4V, rho = 4430. R_t = 4,2 GPa, dopasowanie." } },
		{ "material.ceramic.desc", new string[5] { "Карбид кремния, ro = 3200. R_t = 7.0 ГПа, подгонка по Orphal & Franzen.", "Silicon carbide, rho = 3200. R_t = 7.0 GPa, fitted after Orphal & Franzen.", "", "Siliciumcarbid, rho = 3200. R_t = 7,0 GPa, angepasst nach Orphal & Franzen.", "Weglik krzemu, rho = 3200. R_t = 7,0 GPa, dopasowanie wg Orphal & Franzen." } },
		{ "material.tungsten.desc", new string[5] { "Вольфрам, ro = 17300. R_t = 9.0 ГПа, оценка cavity-expansion.", "Tungsten, rho = 17300. R_t = 9.0 GPa, cavity-expansion estimate.", "", "Wolfram, rho = 17300. R_t = 9,0 GPa, Abschatzung per Hohlraumexpansion.", "Wolfram, rho = 17300. R_t = 9,0 GPa, oszacowanie z rozszerzania kawerny." } },
		{ "material.textolite.desc", new string[5] { "Стеклотекстолит, ro = 1850. ВНИМАНИЕ: R_t = 1.2 ГПа НЕ ПОДТВЕРЖДЁН источником, и модель здесь экстраполируется: ткань расслаивается, а не течёт.", "Glass textolite, rho = 1850. WARNING: R_t = 1.2 GPa is NOT BACKED by a source, and the model is extrapolated here: the fabric delaminates rather than flows.", "", "Glasgewebe-Schichtstoff, rho = 1850. ACHTUNG: R_t = 1,2 GPa ist NICHT durch eine Quelle belegt, und das Modell wird hier extrapoliert: das Gewebe delaminiert, statt zu fliessen.", "Tekstolit szklany, rho = 1850. UWAGA: R_t = 1,2 GPa NIE JEST potwierdzone zrodlem, a model jest tu ekstrapolowany: tkanina rozwarstwia sie, a nie plynie." } },
		{ "material.boroncarbide.desc", new string[5] { "Карбид бора B4C, ro = 2520 (MEASURED). R_t = 6.0 ГПа - FITTED, Orphal/Franzen 1997 (40 опытов, WHA L/D 20). ЕДИНСТВЕННЫЙ материал, чьё сопротивление ПАДАЕТ с ростом давления: выше ~40 ГПа (DERIVED, излом Гюгонио) структура аморфизуется и прочность обваливается. Против стержней порог НЕ достигается никогда, против головной части струи - достигается. ВНИМАНИЕ: R_деград - ASSUMED, БЕЗ ИСТОЧНИКА. HEL 14-19 ГПа - ДРУГАЯ величина, не R_t.", "Boron carbide B4C, rho = 2520 (MEASURED). R_t = 6.0 GPa - FITTED, Orphal/Franzen 1997 (40 shots, WHA L/D 20). The ONLY material whose resistance DROPS as pressure rises: above ~40 GPa (DERIVED, Hugoniot kink) the structure amorphises and strength collapses. Against rods the threshold is NEVER reached; against the jet tip it is. WARNING: R_degraded is ASSUMED, NO SOURCE. HEL 14-19 GPa is a DIFFERENT quantity, not R_t.", "", "Borcarbid B4C, rho = 2520 (MEASURED). R_t = 6,0 GPa - FITTED, Orphal/Franzen 1997 (40 Versuche, WHA L/D 20). Das EINZIGE Material, dessen Widerstand mit steigendem Druck FAELLT: oberhalb ~40 GPa (DERIVED, Hugoniot-Knick) amorphisiert die Struktur und die Festigkeit bricht ein. Gegen Stabe wird die Schwelle NIE erreicht, gegen die Strahlspitze schon. ACHTUNG: R_degradiert ist ASSUMED, OHNE QUELLE. HEL 14-19 GPa ist eine ANDERE Groesse, nicht R_t.", "Weglik boru B4C, rho = 2520 (MEASURED). R_t = 6,0 GPa - FITTED, Orphal/Franzen 1997 (40 prob, WHA L/D 20). JEDYNY material, ktorego opor SPADA ze wzrostem cisnienia: powyzej ~40 GPa (DERIVED, zalamanie Hugoniota) struktura amorfizuje sie i wytrzymalosc zalamuje sie. Wobec rdzeni prog NIGDY nie jest osiagany, wobec czola strumienia - jest. UWAGA: R_zdegradowane jest ASSUMED, BEZ ZRODLA. HEL 14-19 GPa to INNA wielkosc, nie R_t." } },
		{ "material.titaniumdiboride.desc", new string[5] { "Диборид титана TiB2, ro = 4500 (MEASURED). R_t СПАДАЕТ ПО ГЛУБИНЕ: 10.7 -> 5.8 ГПа по мере измельчения керамики (обе точки FITTED, Hauver/Gooch 1992, WHA 1500 м/с). ВНИМАНИЕ: 8.4 ГПа из того же источника - ПУТЕВОЕ СРЕДНЕЕ, а не третья стадия, и в модели не используется. Длина спада - ASSUMED, БЕЗ ИСТОЧНИКА. Вязкость разрушения входит ТОЛЬКО как скорость спада; многократное попадание вне модели.", "Titanium diboride TiB2, rho = 4500 (MEASURED). R_t DECAYS WITH DEPTH: 10.7 -> 5.8 GPa as the ceramic comminutes (both points FITTED, Hauver/Gooch 1992, WHA 1500 m/s). WARNING: the 8.4 GPa from the same source is a PATH AVERAGE, not a third stage, and is not used by the model. The decay length is ASSUMED, NO SOURCE. Fracture toughness enters ONLY as the decay rate; repeat hits are outside the model.", "", "Titandiborid TiB2, rho = 4500 (MEASURED). R_t FAELLT MIT DER TIEFE: 10,7 -> 5,8 GPa mit fortschreitender Zertrummerung der Keramik (beide Punkte FITTED, Hauver/Gooch 1992, WHA 1500 m/s). ACHTUNG: die 8,4 GPa aus derselben Quelle sind ein WEGMITTEL, keine dritte Stufe, und werden im Modell nicht verwendet. Die Abfalllange ist ASSUMED, OHNE QUELLE. Die Bruchzahigkeit geht NUR als Abfallrate ein; Mehrfachtreffer liegen ausserhalb des Modells.", "Dwuborek tytanu TiB2, rho = 4500 (MEASURED). R_t MALEJE Z GLEBOKOSCIA: 10,7 -> 5,8 GPa w miare rozdrabniania ceramiki (oba punkty FITTED, Hauver/Gooch 1992, WHA 1500 m/s). UWAGA: 8,4 GPa z tego samego zrodla to SREDNIA PO DRODZE, a nie trzeci etap, i nie jest uzywana w modelu. Dlugosc spadku jest ASSUMED, BEZ ZRODLA. Odpornosc na pekanie wchodzi TYLKO jako tempo spadku; wielokrotne trafienia poza modelem." } },
		{ "material.alumina.desc", new string[5] { "Оксид алюминия AD995, ro = 3900 (MEASURED). R_t = 5.8 ГПа - FITTED, Hohler/Stilp/Weber 1995 (критическая скорость: 5.4/6.1/4.8 ГПа на 1.7/2.5/3.0 км/с). Источник отмечает отсутствие заметной скоростной зависимости - поэтому строка постоянная по ЕГО утверждению, а не по нашему упрощению.", "Alumina AD995, rho = 3900 (MEASURED). R_t = 5.8 GPa - FITTED, Hohler/Stilp/Weber 1995 (critical velocity: 5.4/6.1/4.8 GPa at 1.7/2.5/3.0 km/s). The source reports no appreciable velocity dependence - so the entry is constant on ITS claim, not on our simplification.", "", "Aluminiumoxid AD995, rho = 3900 (MEASURED). R_t = 5,8 GPa - FITTED, Hohler/Stilp/Weber 1995 (kritische Geschwindigkeit: 5,4/6,1/4,8 GPa bei 1,7/2,5/3,0 km/s). Die Quelle nennt keine nennenswerte Geschwindigkeitsabhangigkeit - der Eintrag ist also nach IHRER Aussage konstant, nicht durch unsere Vereinfachung.", "Tlenek glinu AD995, rho = 3900 (MEASURED). R_t = 5,8 GPa - FITTED, Hohler/Stilp/Weber 1995 (predkosc krytyczna: 5,4/6,1/4,8 GPa przy 1,7/2,5/3,0 km/s). Zrodlo nie stwierdza zauwazalnej zaleznosci od predkosci - wpis jest wiec staly wedlug JEGO twierdzenia, a nie naszego uproszczenia." } },
		{ "material.depleteduraniumarmour.desc", new string[5] { "Обеднённый уран как БРОНЯ, ro = 18600 (MEASURED). R_t = 5.8 ГПа - DERIVED: R_t = Y*[2/3 + ln(2E/3Y)] (Hill 1950, принято Тейтом 1986) при Y = 1.1 ГПа, E = 208 ГПа, с поверкой метода на RHA (даёт 5.56 против измеренных 5.3, +5%). ВНИМАНИЕ: ИЗМЕРЕНИЙ R_t ДЛЯ УРАНА-МИШЕНИ НЕТ ВОВСЕ. Его защита - это ПЛОТНОСТЬ, которая работает отдельным инерционным членом 0.5*ro*u^2; выводить из неё ещё и высокое R_t = считать дважды.", "Depleted uranium as ARMOUR, rho = 18600 (MEASURED). R_t = 5.8 GPa - DERIVED: R_t = Y*[2/3 + ln(2E/3Y)] (Hill 1950, adopted by Tate 1986) with Y = 1.1 GPa, E = 208 GPa, the method checked against RHA (gives 5.56 vs 5.3 measured, +5%). WARNING: THERE ARE NO MEASUREMENTS OF R_t FOR URANIUM AS A TARGET AT ALL. Its protection is DENSITY, which acts through the separate inertial term 0.5*rho*u^2; deriving a high R_t from it as well would be counting twice.", "", "Abgereichertes Uran als PANZERUNG, rho = 18600 (MEASURED). R_t = 5,8 GPa - DERIVED: R_t = Y*[2/3 + ln(2E/3Y)] (Hill 1950, von Tate 1986 uebernommen) bei Y = 1,1 GPa, E = 208 GPa, Methode an RHA geprueft (ergibt 5,56 gegen 5,3 gemessen, +5%). ACHTUNG: MESSUNGEN VON R_t FUER URAN ALS ZIEL GIBT ES UEBERHAUPT NICHT. Sein Schutz ist die DICHTE, die ueber den separaten Traegheitsterm 0,5*rho*u^2 wirkt; daraus zusatzlich ein hohes R_t abzuleiten hiesse doppelt zu zahlen.", "Uran zubozony jako PANCERZ, rho = 18600 (MEASURED). R_t = 5,8 GPa - DERIVED: R_t = Y*[2/3 + ln(2E/3Y)] (Hill 1950, przyjete przez Tate'a 1986) przy Y = 1,1 GPa, E = 208 GPa, metoda sprawdzona na RHA (daje 5,56 wobec 5,3 zmierzonych, +5%). UWAGA: POMIAROW R_t DLA URANU JAKO CELU NIE MA WCALE. Jego ochrona to GESTOSC, dzialajaca przez osobny czlon bezwladnosciowy 0,5*rho*u^2; wyprowadzanie z niej dodatkowo wysokiego R_t oznaczaloby liczenie dwa razy." } },
		{ "core.wha", new string[5] { "Вольфрам. сплав", "Tungsten alloy", "", "Wolframlegierung", "Stop wolframu" } },
		{ "core.du", new string[5] { "Обедн. уран", "Depleted uranium", "", "Abgereich. Uran", "Uran zubozony" } },
		{ "core.steel", new string[5] { "Сталь 4340", "4340 steel", "", "Stahl 4340", "Stal 4340" } },
		{ "core.wc", new string[5] { "Карбид W", "Tungsten carbide", "", "Wolframcarbid", "Weglik wolframu" } },
		{ "core.wha.desc", new string[5] { "ro = 17300, Y_p = 2.0 ГПа. Классический БОПС.", "rho = 17300, Y_p = 2.0 GPa. The classic long-rod penetrator.", "", "rho = 17300, Y_p = 2,0 GPa. Der klassische Wuchtgeschoss-Penetrator.", "rho = 17300, Y_p = 2,0 GPa. Klasyczny penetrator podkalibrowy." } },
		{ "core.du.desc", new string[5] { "ro = 18600, Y_p = 1.1 ГПа. Самозатачивается при эрозии.", "rho = 18600, Y_p = 1.1 GPa. Self-sharpens as it erodes.", "", "rho = 18600, Y_p = 1,1 GPa. Schaerft sich beim Abtrag selbst nach.", "rho = 18600, Y_p = 1,1 GPa. Samoostrzy sie podczas erozji." } },
		{ "core.steel.desc", new string[5] { "ro = 7850, Y_p = 1.5 ГПа. Втрое легче вольфрама.", "rho = 7850, Y_p = 1.5 GPa. Three times lighter than tungsten.", "", "rho = 7850, Y_p = 1,5 GPa. Dreimal leichter als Wolfram.", "rho = 7850, Y_p = 1,5 GPa. Trzy razy lzejszy od wolframu." } },
		{ "core.wc.desc", new string[5] { "ro = 15000, Y_p = 5.0 ГПа. Хрупкий: колется, а не гнётся.", "rho = 15000, Y_p = 5.0 GPa. Brittle: it shatters instead of bending.", "", "rho = 15000, Y_p = 5,0 GPa. Sproede: er zerspringt, statt sich zu biegen.", "rho = 15000, Y_p = 5,0 GPa. Kruchy: peka, zamiast sie giac." } },
		{ "object.plate", new string[5] { "Преграда", "Barrier", "", "Hindernis", "Przegroda" } },
		{ "object.screen", new string[5] { "Экран", "Screen", "", "Schurze", "Ekran" } },
		{ "object.slat", new string[5] { "Решётка", "Slat cage", "", "Kafiggitter", "Krata" } },
		{ "object.engineblock", new string[5] { "Моторный отсек", "Engine bay", "", "Motorraum", "Komora silnika" } },
		{ "object.era", new string[5] { "Кассета ДЗ", "ERA cassette", "", "ERA-Kassette", "Kaseta ERA" } },
		{ "object.nera", new string[5] { "Блок НДЗ", "NERA block", "", "NERA-Block", "Blok NERA" } },
		{ "object.spallliner", new string[5] { "Подбой", "Spall liner", "", "Splitterschutz", "Wyscielka" } },
		{ "object.crew", new string[5] { "Экипаж", "Crew", "", "Besatzung", "Zaloga" } },
		{ "object.plate.desc", new string[5] { "Обычная преграда: материал и толщина задаются отдельно.", "An ordinary barrier: material and thickness are set separately.", "", "Ein gewoehnliches Hindernis: Material und Dicke werden getrennt eingestellt.", "Zwykla przegroda: material i grubosc ustawiane osobno." } },
		{ "object.era.desc", new string[5] { "Кассета динамической защиты - САМОСТОЯТЕЛЬНЫЙ объект своего размера (W*W*набивка), собранный из отдельных частей: короб, метаемая пластина, прослойка, опорная пластина, крепление. Массив набирается размещением НЕСКОЛЬКИХ кассет - соседи независимы по построению, потому что это разные объекты. ВНИМАНИЕ: t_p, V_p, зазор и W - PLACEHOLDER, но входят в расчёт: редактор пишет в те же поля, которые читает ReactiveArmor.", "An explosive reactive armour cassette is a SELF-CONTAINED object of its own size (W*W*stack), built from separate parts: box, flyer plate, interlayer, backing plate, mount. An array is made by placing SEVERAL cassettes - neighbours are independent by construction, because they are separate objects. WARNING: t_p, V_p, gap and W are PLACEHOLDER, yet they DO enter the solve: the editor writes into the very fields ReactiveArmor reads.", "", "Eine Kassette der Reaktivpanzerung ist ein EIGENSTAENDIGES Objekt eigener Groesse (W*W*Paket), aus Einzelteilen aufgebaut: Kasten, Flugplatte, Zwischenlage, Stuetzplatte, Halterung. Ein Feld entsteht durch Platzieren MEHRERER Kassetten - Nachbarn sind konstruktionsbedingt unabhaengig, denn es sind verschiedene Objekte. ACHTUNG: t_p, V_p, Spalt und W sind PLACEHOLDER, gehen aber in die Rechnung ein: der Editor schreibt in genau die Felder, die ReactiveArmor liest.", "Kaseta pancerza reaktywnego to SAMODZIELNY obiekt o wlasnym rozmiarze (W*W*wypelnienie), zlozony z osobnych czesci: skrzynka, plyta miotana, przekladka, plyta oporowa, mocowanie. Uklad tworzy sie przez umieszczenie KILKU kaset - sasiedzi sa niezalezni z konstrukcji, bo to rozne obiekty. UWAGA: t_p, V_p, szczelina i W to PLACEHOLDER, ale wchodza do obliczen: edytor pisze do tych samych pol, ktore czyta ReactiveArmor." } },
		{ "object.nera.desc", new string[5] { "Блок НДЗ: две пластины в эластомере - тот же механизм подачи свежего металла, что у ДЗ, но привод не взрывной. СКОРОСТИ ПЛАСТИН НЕ ЗАДАЮТСЯ, А ВЫВОДЯТСЯ из одного импульса: V = J/(ro*t), поэтому тонкая передняя уходит быстрее толстой задней (3/5 мм даёт ровно x1.667). ВНИМАНИЕ: импульс эластомера - ASSUMED, БЕЗ ИСТОЧНИКА: измеренных скоростей пластин НДЗ в открытой литературе нет. Из акустического импеданса он НЕ выведен - импеданс объясняет механизм, а не величину. Предзаряд тандема НДЗ не снимает: взрывать в блоке нечего.", "A NERA block: two plates in an elastomer - the same fresh-metal feed mechanism as ERA, but the drive is not explosive. THE PLATE VELOCITIES ARE NOT SET, THEY ARE DERIVED from a single impulse: V = J/(rho*t), so the thin front plate leaves faster than the thick rear one (3/5 mm gives exactly x1.667). WARNING: the elastomer impulse is ASSUMED, NO SOURCE: no measured NERA plate velocities exist in the open literature. It is NOT derived from acoustic impedance - impedance explains the mechanism, not the magnitude. A tandem precursor does not defeat NERA: there is nothing in the block to detonate.", "", "NERA-Block: zwei Platten in einem Elastomer - derselbe Mechanismus der Frischmetallzufuhr wie bei ERA, aber der Antrieb ist nicht explosiv. DIE PLATTENGESCHWINDIGKEITEN WERDEN NICHT VORGEGEBEN, SONDERN ABGELEITET aus einem einzigen Impuls: V = J/(rho*t), daher loest sich die duenne Frontplatte schneller als die dicke Rueckplatte (3/5 mm ergibt genau x1,667). ACHTUNG: der Elastomerimpuls ist ASSUMED, OHNE QUELLE: gemessene NERA-Plattengeschwindigkeiten gibt es in der offenen Literatur nicht. Aus der akustischen Impedanz ist er NICHT abgeleitet - die Impedanz erklaert den Mechanismus, nicht den Betrag. Eine Tandem-Vorladung raeumt NERA nicht: im Block gibt es nichts zu zuenden.", "Blok NERA: dwie plyty w elastomerze - ten sam mechanizm podawania swiezego metalu co w ERA, ale naped nie jest wybuchowy. PREDKOSCI PLYT NIE SA ZADAWANE, LECZ WYPROWADZANE z jednego impulsu: V = J/(rho*t), dlatego cienka plyta przednia odchodzi szybciej niz gruba tylna (3/5 mm daje dokladnie x1,667). UWAGA: impuls elastomeru jest ASSUMED, BEZ ZRODLA: zmierzonych predkosci plyt NERA w otwartej literaturze nie ma. Nie wyprowadzono go z impedancji akustycznej - impedancja tlumaczy mechanizm, a nie wartosc. Ladunek wyprzedzajacy tandemu nie usuwa NERA: w bloku nie ma czego detonowac." } },
		{ "object.spallliner.desc", new string[5] { "Противоосколочный подбой: ткань (арамид/СВМПЭ), которая ЛОВИТ ОСКОЛКИ растяжением волокон. НЕ материал брони и не преграда: снаряд по линии визирования он не задерживает (модели его сопротивления лому нет), его работа начинается ПОСЛЕ пробития. Управляющая величина - поверхностная плотность ro*t, поэтому толщина входит в расчёт напрямую. ВНИМАНИЕ: порог поглощения у арамида - ASSUMED, БЕЗ ИСТОЧНИКА. СВМПЭ лучше на единицу массы - это установлено качественно, но отношение x1.5 ПРЕДПОЛОЖЕНО.", "An anti-spall liner: fabric (aramid/UHMWPE) that CATCHES FRAGMENTS by stretching its fibres. NOT an armour material and not a barrier: it does not slow the penetrator along the line of sight (no model of its resistance to a rod exists), its job starts AFTER perforation. The controlling quantity is areal density rho*t, so thickness enters the solve directly. WARNING: the aramid absorption threshold is ASSUMED, NO SOURCE. UHMWPE being better per unit mass is established qualitatively, but the x1.5 ratio is ASSUMED.", "", "Splitterschutzauskleidung: Gewebe (Aramid/UHMWPE), das SPLITTER durch Dehnung der Fasern AUFFAENGT. KEIN Panzermaterial und kein Hindernis: das Geschoss wird entlang der Sichtlinie nicht gebremst (ein Modell seines Widerstands gegen einen Stab existiert nicht), seine Arbeit beginnt NACH dem Durchschlag. Massgebende Groesse ist die Flaechendichte rho*t, daher geht die Dicke direkt in die Rechnung ein. ACHTUNG: die Absorptionsschwelle von Aramid ist ASSUMED, OHNE QUELLE. Dass UHMWPE pro Masseneinheit besser ist, gilt qualitativ, das Verhaeltnis x1,5 ist jedoch ANGENOMMEN.", "Wyscielka przeciwodpryskowa: tkanina (aramid/UHMWPE), ktora LAPIE ODLAMKI przez rozciaganie wlokien. NIE jest materialem pancerza ani przegroda: nie zatrzymuje pocisku wzdluz linii celowania (modelu jej oporu wobec rdzenia nie ma), jej praca zaczyna sie PO przebiciu. Wielkoscia sterujaca jest gestosc powierzchniowa rho*t, wiec grubosc wchodzi do obliczen wprost. UWAGA: prog pochlaniania aramidu jest ASSUMED, BEZ ZRODLA. To, ze UHMWPE jest lepszy na jednostke masy, ustalono jakosciowo, ale stosunek x1,5 jest ZALOZONY." } },
		{ "object.crew.desc", new string[5] { "Фигура экипажа: манекен, регистрирующий попадания осколков. Смысл брони - выживание экипажа, и без того, кого защищают, подбой остаётся абстракцией. Представление намеренно абстрактное: ни анатомии, ни повреждений тела. ВНИМАНИЕ: МОДЕЛЬ СЧИТАЕТ ПОПАДАНИЯ И ЭНЕРГИЮ И НЕ ПРЕДСКАЗЫВАЕТ ПОРАЖЕНИЕ: раневой баллистики в проекте нет, ВСЕ пороги ASSUMED без источника. Преградой не является - снаряд сквозь фигуру не считается вовсе.", "A crew figure: a mannequin that registers fragment hits. The point of armour is crew survival, and without someone being protected a spall liner stays an abstraction. The representation is deliberately abstract: no anatomy, no wounds. WARNING: THE MODEL COUNTS HITS AND ENERGY AND DOES NOT PREDICT INJURY: there is no wound ballistics in this project, ALL thresholds are ASSUMED without a source. It is not a barrier - the penetrator is not resolved through the figure at all.", "", "Besatzungsfigur: eine Puppe, die Splittertreffer registriert. Der Sinn von Panzerung ist das Ueberleben der Besatzung, und ohne jemanden, der geschuetzt wird, bleibt der Splitterschutz eine Abstraktion. Die Darstellung ist bewusst abstrakt: keine Anatomie, keine Verletzungen. ACHTUNG: DAS MODELL ZAEHLT TREFFER UND ENERGIE UND SAGT KEINE VERWUNDUNG VORHER: Wundballistik gibt es in diesem Projekt nicht, ALLE Schwellen sind ASSUMED ohne Quelle. Es ist kein Hindernis - das Geschoss wird durch die Figur gar nicht gerechnet.", "Figura zalogi: manekin rejestrujacy trafienia odlamkow. Sensem pancerza jest przezycie zalogi, a bez kogos chronionego wyscielka pozostaje abstrakcja. Przedstawienie jest celowo abstrakcyjne: bez anatomii, bez obrazen. UWAGA: MODEL LICZY TRAFIENIA I ENERGIE, A NIE PRZEWIDUJE OBRAZEN: balistyki ranowej w projekcie nie ma, WSZYSTKIE progi sa ASSUMED bez zrodla. Nie jest przegroda - pocisk przez figure nie jest liczony wcale." } },
		{ "object.engineblock.desc", new string[5] { "Моторный отсек: объём материала с пустотами. Пустотность снимает ТОЛЩИНУ (t_эфф = (1-f)*t), а материал остаётся собой - полные ro и R_t. ВНИМАНИЕ: ОДНОРОДНОЕ ПРИБЛИЖЕНИЕ: настоящий путь зависит от точки входа (цилиндр или полость), модель даёт СРЕДНЕЕ. Пустотность 0.55 - ASSUMED. Сталь берётся строкой RHA - единственной стальной с источником.", "Engine bay: a volume of material with voids. The void fraction removes THICKNESS (t_eff = (1-f)*t) while the material stays itself - full rho and R_t. WARNING: A HOMOGENEOUS APPROXIMATION: the real path depends on the entry point (cylinder or cavity), the model gives an AVERAGE. The 0.55 void fraction is ASSUMED. Steel uses the RHA entry - the only steel one with a source.", "", "Motorraum: ein Materialvolumen mit Hohlraeumen. Der Hohlraumanteil nimmt DICKE weg (t_eff = (1-f)*t), das Material bleibt es selbst - volle rho und R_t. ACHTUNG: HOMOGENE NAEHERUNG: der tatsaechliche Weg haengt vom Eintrittspunkt ab (Zylinder oder Hohlraum), das Modell liefert einen MITTELWERT. Der Hohlraumanteil 0,55 ist ASSUMED. Fuer Stahl wird der RHA-Eintrag genommen - der einzige Stahleintrag mit Quelle.", "Komora silnika: objetosc materialu z pustkami. Udzial pustek zabiera GRUBOSC (t_eff = (1-f)*t), a material pozostaje soba - pelne rho i R_t. UWAGA: PRZYBLIZENIE JEDNORODNE: rzeczywista droga zalezy od punktu wejscia (cylinder czy pustka), model daje SREDNIA. Udzial pustek 0,55 jest ASSUMED. Stal brana jest z wpisu RHA - jedynego stalowego ze zrodlem." } },
