		{ "proj.wha_rod.desc", new string[5] { "Вольфрамовый стержень, L/D = 10. Расчёт по Тейту.", "Tungsten rod, L/D = 10. Solved with Tate.", "", "Wolframstab, L/D = 10. Berechnung nach Tate.", "Rdzen wolframowy, L/D = 10. Obliczenia wg Tate'a." } },
		{ "proj.du_rod.desc", new string[5] { "Урановый стержень, L/D = 15, самозатачивается. Тейт.", "Uranium rod, L/D = 15, self-sharpening. Tate.", "", "Uranstab, L/D = 15, selbstschaerfend. Tate.", "Rdzen uranowy, L/D = 15, samoostrzacy. Tate." } },
		{ "proj.steel_ap.desc", new string[5] { "Короткий, тупой нос, калибр 40 мм. Тейт.", "Short, blunt nose, 40 mm calibre. Tate.", "", "Kurz, stumpfe Spitze, Kaliber 40 mm. Tate.", "Krotki, tepy nos, kaliber 40 mm. Tate." } },
		{ "proj.wc_core.desc", new string[5] { "Короткий сердечник, коническое остриё, калибр 25 мм. Тейт.", "Short core, conical tip, 25 mm calibre. Tate.", "", "Kurzer Kern, konische Spitze, Kaliber 25 mm. Tate.", "Krotki rdzen, stozkowy czubek, kaliber 25 mm. Tate." } },
		{ "proj.heat_85.desc", new string[5] { "Струя, калибр 85 мм, стандоф 2.0 CD. Другое ядро, не Тейт.", "Jet, 85 mm calibre, 2.0 CD standoff. A different core, not Tate.", "", "Strahl, Kaliber 85 mm, Abstand 2,0 CD. Anderer Kern, nicht Tate.", "Strumien, kaliber 85 mm, odstep 2,0 CD. Inny rdzen, nie Tate." } },
		{ "proj.heat_tandem.desc", new string[5] { "Предзаряд снимает кассету ДЗ, основной заряд идёт по уже инертной. ВНИМАНИЕ: калибр предзаряда и задержка между зарядами - PLACEHOLDER. Предзаряд НЕ считается отдельным пробитием: его работа - инициировать кассету.", "The precursor clears the ERA cassette, the main charge then passes an already inert one. WARNING: the precursor calibre and the inter-charge delay are PLACEHOLDER. The precursor is NOT scored as a separate penetration: its job is to initiate the cassette.", "", "Die Vorladung raeumt die ERA-Kassette, die Hauptladung trifft dann eine bereits inerte. ACHTUNG: Kaliber der Vorladung und Verzoegerung zwischen den Ladungen sind PLACEHOLDER. Die Vorladung wird NICHT als eigener Durchschlag gewertet: ihre Aufgabe ist das Ausloesen der Kassette.", "Ladunek wyprzedzajacy usuwa kasete ERA, ladunek glowny idzie juz przez bezwladna. UWAGA: kaliber ladunku wyprzedzajacego i opoznienie miedzy ladunkami to PLACEHOLDER. Ladunek wyprzedzajacy NIE jest liczony jako osobne przebicie: jego zadaniem jest zainicjowanie kasety." } },
		{ "proj.etalon_rod.desc", new string[5] { "WHA L/D = 10, Ø 30 мм, 1100 м/с, ПЛОСКИЙ торец. Та самая постановка, на которой сняты отпечаток решателя и все замеры этого проекта: ворота набора идут именно на плоском носе.", "WHA L/D = 10, 30 mm calibre, 1100 m/s, FLAT nose. The configuration the solver fingerprint and every recorded measurement rest on: the gate set runs on a flat nose.", "", "", "" } },
