		{ "sandbox.nera_bond.bonded", new string[5] { "СВЯЗАН - пластины приклеены к прослойке; единственная связанность, которую сетка выражает", "BONDED - the plates are glued to the interlayer; the only bonding the grid can express", "БӘЙЛӘНГӘН - пластиналар катламга ябыштырылган; челтәр әйтә ала торган бердәнбер бәйләнеш", "VERBUNDEN - die Platten sind mit der Zwischenschicht verklebt; die einzige Bindung, die das Gitter ausdrücken kann", "ZWIĄZANY - płyty są sklejone z przekładką; jedyne związanie, które siatka potrafi wyrazić" } },
		{ "sandbox.nera_bond.unbonded", new string[5] { "НЕ СВЯЗАН - Super ОТКАЖЕТ: у сеточного контакта нет скольжения, отпустить пластину нечем", "UNBONDED - Super WILL REFUSE: the grid contact has no sliding, there is nothing to release the plate with", "БӘЙЛӘНМӘГӘН - Super КИРЕ КАГА: челтәр контактында шуу юк, пластинаны җибәрер әйбер юк", "UNVERBUNDEN - Super LEHNT AB: der Gitterkontakt hat kein Gleiten, die Platte kann nicht gelöst werden", "NIEZWIĄZANY - Super ODMÓWI: kontakt siatkowy nie ma poślizgu, nie ma czym zwolnić płyty" } },
		{ "sandbox.nera_bond.unknown", new string[5] { "НЕ НАЗВАНА - считается связанным, и это ПЕЧАТАЕТСЯ в паспорте прогона, а не подразумевается", "NOT STATED - treated as bonded, and that is PRINTED in the run passport rather than assumed silently", "АТАЛМАГАН - бәйләнгән дип санала, һәм бу узышу паспортында ЯЗЫЛА, ә тик кенә фаразланмый", "NICHT GENANNT - gilt als verbunden, und das wird im Laufpass GEDRUCKT statt stillschweigend angenommen", "NIEPODANE - traktowany jako związany, i jest to WYPISANE w paszporcie przebiegu, a nie milcząco założone" } },
		{ "sandbox.nera_interlayer_j", new string[5] { "В ОБЫЧНОМ РЕЖИМЕ ЧИСЕЛ ВЫСТРЕЛА ЭТОТ ВЫБОР НЕ МЕНЯЕТ: импульса прослойки по материалам в литературе НЕТ, а вывести его из адиабаты можно только гидрокодом. В SUPER (гидрокод) прослойка считается строкой реестра (ниже), и там выбор числа МЕНЯЕТ.", "IN NORMAL MODE THIS CHOICE DOES NOT CHANGE ANY SHOT NUMBER: the literature has NO interlayer impulse per material, and deriving one from the Hugoniot needs a hydrocode. In SUPER (a hydrocode) the interlayer is computed by its registry row (below), and there the choice DOES change the numbers.", "ГАДИ РЕЖИМДА БУ САЙЛАУ АТУ САННАРЫН ҮЗГӘРТМИ: әдәбиятта катламның материалга карата импульсы ЮК, ә аны адиабатадан чыгару өчен гидрокод кирәк. SUPER режимында (гидрокод) катлам реестр юлы белән санала (түбәндә), һәм анда сайлау саннарны ҮЗГӘРТӘ.", "IM NORMALMODUS ÄNDERT DIESE WAHL KEINE SCHUSSZAHL: die Literatur kennt KEINEN Zwischenschicht-Impuls je Werkstoff, und ihn aus der Hugoniot-Kurve abzuleiten bräuchte einen Hydrocode. In SUPER (einem Hydrocode) wird die Zwischenschicht über ihre Registerzeile gerechnet (unten), und dort ÄNDERT die Wahl die Zahlen.", "W TRYBIE ZWYKŁYM TEN WYBÓR NIE ZMIENIA ŻADNEJ LICZBY STRZAŁU: literatura NIE podaje impulsu przekładki dla materiałów, a wyprowadzenie go z adiabaty wymaga hydrokodu. W SUPER (hydrokod) przekładka liczona jest swoim wierszem rejestru (niżej) i tam wybór ZMIENIA liczby." } },
		{ "sandbox.nera_state_row", new string[5] { "Пакет из каталога: «{0}».", "Catalogue pack: “{0}”.", "Каталогтан пакет: «{0}».", "Paket aus dem Katalog: „{0}“.", "Pakiet z katalogu: „{0}”." } },
		{ "sandbox.nera_state_custom", new string[5] { "СОБРАН ИГРОКОМ - это НЕ ИЗМЕРЕННЫЙ ПАКЕТ. У строки каталога состояния два (измеренный отстрел либо умолчание проекта); у этого пакета третье, и оно называется здесь. Геометрия и вещества взяты из проверенных пределов, но такой сборки никто не отстреливал.", "BUILT BY THE PLAYER - this is NOT A MEASURED PACK. A catalogue row has two states (a measured firing test or a project default); this pack is the third, and it is named here. The geometry and materials come from checked ranges, but nobody has ever fired this assembly.", "УЕНЧЫ ҖЫЙГАН - бу ҮЛЧӘНГӘН ПАКЕТ ТҮГЕЛ. Каталог юлының ике халәте бар (үлчәнгән ату яки проект килешүе); бу пакетта өченчесе, һәм ул монда атала. Геометрия һәм матдәләр тикшерелгән чикләрдән алынган, ләкин бу җыелманы беркем аткан юк.", "VOM SPIELER GEBAUT - das ist KEIN GEMESSENES PAKET. Eine Katalogzeile hat zwei Zustände (gemessener Beschuss oder Projekt-Voreinstellung); dieses Paket ist der dritte, und er wird hier genannt. Geometrie und Werkstoffe stammen aus geprüften Grenzen, aber diesen Aufbau hat nie jemand beschossen.", "ZBUDOWANY PRZEZ GRACZA - to NIE JEST PAKIET ZMIERZONY. Wiersz katalogu ma dwa stany (zmierzony ostrzał albo domyślna wartość projektu); ten pakiet ma trzeci i jest on tu nazwany. Geometria i materiały pochodzą ze sprawdzonych zakresów, ale tego układu nikt nigdy nie ostrzelał." } },
		{ "sandbox.nera_layers", new string[5] { "Слоёв частиц при шаге {9:F2} мм: {0}/{1}/{2}. Запечётся {3:F2}/{4:F2}/{5:F2} мм - расхождение с заказанным {6:P1}/{7:P1}/{8:P1}. Масса всех трёх слоёв входит в механизм.", "Particle layers at a {9:F2} mm spacing: {0}/{1}/{2}. Baked thicknesses {3:F2}/{4:F2}/{5:F2} mm - difference from what you ordered {6:P1}/{7:P1}/{8:P1}. The mass of all three layers enters the mechanism.", "{9:F2} мм адымда кисәкчә катламнары: {0}/{1}/{2}. Пешерелә {3:F2}/{4:F2}/{5:F2} мм - соралганнан аерма {6:P1}/{7:P1}/{8:P1}. Өч катламның да массасы механизмга керә.", "Partikellagen bei {9:F2} mm Abstand: {0}/{1}/{2}. Gebacken werden {3:F2}/{4:F2}/{5:F2} mm - Abweichung vom Bestellten {6:P1}/{7:P1}/{8:P1}. Die Masse aller drei Lagen geht in den Mechanismus ein.", "Warstwy cząstek przy kroku {9:F2} mm: {0}/{1}/{2}. Wypiecze się {3:F2}/{4:F2}/{5:F2} mm - różnica wobec zamówionego {6:P1}/{7:P1}/{8:P1}. Masa wszystkich trzech warstw wchodzi do mechanizmu." } },
