		{ "ultra.reject.no_plates", new string[5] { "В сцене нет ни одной плиты.", "The scene contains no plate.", "", "", "" } },
		{ "ultra.reject.yaw", new string[5] { "Рыскание снаряда не равно нулю: такой удар не осесимметричен.", "Projectile yaw is non-zero: the impact is not axisymmetric.", "", "", "" } },
		{ "ultra.reject.curved", new string[5] { "Криволинейная преграда: ось симметрии у такой мишени не определена.", "Curved target: no axis of symmetry is defined for it.", "", "", "" } },
		{ "ultra.reject.off_axis", new string[5] { "Плита смещена от оси выстрела: удар не по центру, задача не осесимметрична.", "The plate is offset from the shot axis: the impact is off-centre and not axisymmetric.", "", "", "" } },
		{ "ultra.reject.overlap", new string[5] { "Плиты перекрывают друг друга по линии выстрела: между соседними слоями получается отрицательный зазор. Раздвиньте их — поджать перекрытие к нулю значило бы посчитать не ту сцену, которую вы собрали.", "The plates overlap along the shot line: the gap between neighbouring layers comes out negative. Move them apart — clamping the overlap to zero would mean solving a scene other than the one you built.", "", "", "" } },
		{ "ultra.reject.material", new string[5] { "Материал вне поддержанного набора решателя.", "Material outside the solver supported set.", "", "", "" } },
		{ "ultra.reject.no_jet_model", new string[5] { "Кумулятивный выстрел: у решателя сплошной среды нет модели струи. Длина и калибр у такого боеприпаса описывают КОРПУС, а не пенетратор, и постановка из них была бы стержнем, которого не существует. Пробитие струёй по-прежнему считает аналитическое ядро — в обычном и продвинутом режимах.", "Shaped charge: the continuum solver carries no jet model. Length and calibre on such a round describe the BODY, not a penetrator, and a setup built from them would be a rod that does not exist. Jet penetration is still computed by the analytic core, in the normal and advanced modes.", "", "", "" } },
		{ "ultra.gates.coverage", new string[5] { "Набор ворот удостоверяет РЕШАТЕЛЬ на перечисленных выше постановках. Форму носа и разрешение сетки принимают извне только T5 и T6; остальные шесть снаряда не строят вовсе (T1, T2, T2b, T7), снимают прочность целиком и потому к форме носа безразличны (T4) или держат тупой нос своей ПОСЫЛКОЙ (T8). Выбранные вами разрешение сетки и форма носа отдельно НЕ удостоверены и у T5 с T6: набор регистрирует их собственный тупоносый прогон на их собственных разрешениях, а не ваш.", "The gate set certifies the SOLVER at the configurations listed above. Only T5 and T6 take the nose shape and the mesh resolution from outside; the other six build no projectile at all (T1, T2, T2b, T7), strip strength entirely and so are indifferent to nose shape (T4), or hold a blunt nose as their PREMISE (T8). The resolution and nose you selected are NOT separately certified even for T5 and T6: the set registers their own blunt-nosed run at their own resolutions, not yours.", "", "", "" } },
		{ "ultra.reject.ricochet", new string[5] { "Рикошет: снаряд не входит, и толщина по линии визирования описывает не тот процесс.", "Ricochet: the projectile does not enter, so line-of-sight thickness describes the wrong process.", "", "", "" } },
		{ "ultra.reject.slide", new string[5] { "Скольжение по преграде: снаряд не входит нормально.", "Sliding along the plate: the projectile does not enter normally.", "", "", "" } },
		{ "ultra.reject.thin_front_layer", new string[5] { "Передний слой тоньше радиуса стержня при нулевом зазоре: слои этой постановки не толкают друг друга, и тонкий слой уходит внутрь второго. Станет доступно, когда появится контакт между слоями (этап 2). Пока — зазор или слой не тоньше радиуса стержня.", "The front layer is thinner than the rod radius and sits flush on the next one: in this setup the layers do not push one another, and the thin layer travels into the second one's space. This becomes available once contact between layers exists (stage 2). For now — leave a gap, or make the layer no thinner than the rod radius.", "", "", "" } },
		{ "ultra.declaration.line_of_sight", new string[5] { "Наклон заменён толщиной по линии визирования при нормальном падении: КАЖДЫЙ слой пересчитан своим косинусом, зазоры отмерены вдоль линии выстрела, а не по нормали к плитам, и весь пакет рисуется перпендикулярным. Кратер будет круглым там, где в натуре эллиптический; наклон плиты, несимметричное вспучивание и геометрия рикошета не показываются. Слои НЕ ТОЛКАЮТ ДРУГ ДРУГА: стержень проходит их по очереди, а осколки через зазор не летят — взаимодействие слоёв между собой эта модель не считает. При нулевом зазоре по ходу события на шве может проступить линия и ступенька в стенке канала — слои расходятся, не толкая друг друга; это та же идеализация, а не дефект показа.", "Tilt is replaced by line-of-sight thickness at normal incidence: EACH layer is projected by its own cosine, gaps are measured along the shot line rather than normal to the plates, and the whole stack is drawn perpendicular. The crater will be round where it is elliptical in reality; plate tilt, asymmetric bulging and ricochet geometry are not shown. Layers DO NOT PUSH ONE ANOTHER: the rod works through them in turn, and debris does not cross the gap — interaction between the layers themselves is not computed by this model. At zero gap a seam line and a small step in the channel wall may appear as the event goes on — the layers drift apart without pushing one another; the same idealisation, not a rendering defect.", "", "", "" } },
		{ "ultra.declaration.caption.tilt", new string[5] { "Наклон {0}° заменён толщиной по линии визирования: {1} мм под углом = {2} мм по нормали. Плита показана ПЕРПЕНДИКУЛЯРНОЙ, форма кратера — как при нормальном ударе.", "Tilt {0}° replaced by line-of-sight thickness: {1} mm at angle = {2} mm at normal incidence. The plate is drawn PERPENDICULAR, and the crater shape is that of a normal hit.", "", "", "" } },
		{ "ultra.declaration.caption.stack", new string[5] { "Пакет из {0} слоёв, {1} мм суммарно по нормали: зазоры отмерены вдоль линии выстрела, и слои НЕ ТОЛКАЮТ ДРУГ ДРУГА.", "Stack of {0} layers, {1} mm total at normal incidence: gaps are measured along the shot line, and the layers DO NOT PUSH ONE ANOTHER.", "", "", "" } },
		{ "ultra.declaration.caption.stack_tilt", new string[5] { "Пакет из {0} слоёв, наклон до {1}°: {2} мм = {3} мм по линии визирования. Пакет показан ПЕРПЕНДИКУЛЯРНЫМ, слои НЕ ТОЛКАЮТ ДРУГ ДРУГА.", "Stack of {0} layers, tilt up to {1}°: {2} mm = {3} mm line-of-sight. The stack is drawn PERPENDICULAR, and the layers DO NOT PUSH ONE ANOTHER.", "", "", "" } },
		{ "ultra.ghost.legend", new string[5] { "Контур — КАК ПОСТРОЕНО: {0} мм под {1}°. Заливка — КАК ПОСЧИТАНО: {2} мм по нормали. Сторона завала взята у построенной плиты; у заваленной ВБОК её в осесимметрии нет — там контур рисуется условно.", "Outline — AS BUILT: {0} mm at {1}°. Solid — AS COMPUTED: {2} mm at normal incidence. Which way it leans is taken from the built plate; for a SIDEWAYS lean axisymmetry has no such side and the outline is drawn by convention.", "", "", "" } },
		{ "ultra.ghost.on", new string[5] { "Призрак построенной плиты: ВКЛ (клавиша {0} — выключить)", "Ghost of the built plate: ON (key {0} to hide)", "", "", "" } },
		{ "ultra.ghost.off", new string[5] { "Призрак построенной плиты: выкл (клавиша {0} — включить)", "Ghost of the built plate: off (key {0} to show)", "", "", "" } },
		{ "ultra.cache.equivalent", new string[5] { "Эта расстановка эквивалентна уже посчитанной: по линии визирования получается та же толщина, поэтому решение взято из кэша, а не считалось заново.", "This configuration is equivalent to one already solved: it yields the same line-of-sight thickness, so the result came from the cache rather than a new solve.", "", "", "" } },
