		{ "super.hud.jet_floor", new string[5] { "Струя диаметром {0:F2} мм требует шаг не крупнее {1:F2} мм — это ниже пола ручки ({2:F2} мм): такой заряд режим не считает.", "A jet {0:F2} mm in diameter needs a spacing no coarser than {1:F2} mm — below the control's floor ({2:F2} mm): this mode does not solve such a charge.", "Диаметры {0:F2} мм булган агым {1:F2} мм дан эре булмаган адым таләп итә — бу көйләгечнең аскы чигеннән түбән ({2:F2} мм): режим мондый зарядны исәпләми.", "Ein Strahl mit {0:F2} mm Durchmesser braucht einen Abstand von höchstens {1:F2} mm — unter der Untergrenze des Reglers ({2:F2} mm): Dieser Modus berechnet eine solche Ladung nicht.", "Strumień o średnicy {0:F2} mm wymaga odstępu nie większego niż {1:F2} mm — poniżej dolnej granicy suwaka ({2:F2} mm): ten tryb nie liczy takiego ładunku." } },
		{ "super.hud.export_toggle", new string[5] { " Сохранять видео сразу после расчёта", " Save video right after solving", " Исәпләүдән соң ук видеоны саклау", " Video direkt nach der Berechnung speichern", " Zapisz wideo zaraz po obliczeniu" } },
