		{ "super.refuse.vram", new string[5] { "Этой сцене нужно {0:F2} ГБ видеопамяти, у вас {1:F2} ГБ (60 % из {2:F2} ГБ карты — выше решатель откажет сам). Влезет при шаге частиц не мельче {3:F2} мм — или уменьшите плиты.", "This scene needs {0:F2} GB of video memory, you have {1:F2} GB (60 % of the card's {2:F2} GB — above that the solver refuses by itself). It fits at a particle spacing of at least {3:F2} mm — or use smaller plates.", "Бу сәхнәгә {0:F2} ГБ видеохәтер кирәк, сездә {1:F2} ГБ (картаның {2:F2} ГБ ның 60 %ы — артыгын исәпләгеч үзе кире кага). Кисәкчә адымы {3:F2} мм дан ким булмаганда сыя — яки пластиналарны кечерәйтегез.", "Diese Szene braucht {0:F2} GB Grafikspeicher, Sie haben {1:F2} GB (60 % der {2:F2} GB der Karte — darüber lehnt der Löser selbst ab). Sie passt ab einem Partikelabstand von {3:F2} mm — oder kleinere Platten verwenden.", "Ta scena potrzebuje {0:F2} GB pamięci wideo, masz {1:F2} GB (60 % z {2:F2} GB karty — powyżej solwer sam odmówi). Zmieści się przy odstępie cząstek co najmniej {3:F2} mm — albo zmniejsz płyty." } },
		{ "super.refuse.vram_nofit", new string[5] { "Этой сцене нужно {0:F2} ГБ видеопамяти, у вас {1:F2} ГБ (60 % из {2:F2} ГБ карты — выше решатель откажет сам). Не влезает даже при самом крупном шаге {3:F2} мм — уменьшите плиты.", "This scene needs {0:F2} GB of video memory, you have {1:F2} GB (60 % of the card's {2:F2} GB — above that the solver refuses by itself). It does not fit even at the coarsest spacing of {3:F2} mm — use smaller plates.", "Бу сәхнәгә {0:F2} ГБ видеохәтер кирәк, сездә {1:F2} ГБ (картаның {2:F2} ГБ ның 60 %ы — артыгын исәпләгеч үзе кире кага). Иң эре {3:F2} мм адымда да сыймый — пластиналарны кечерәйтегез.", "Diese Szene braucht {0:F2} GB Grafikspeicher, Sie haben {1:F2} GB (60 % der {2:F2} GB der Karte — darüber lehnt der Löser selbst ab). Sie passt nicht einmal beim gröbsten Abstand von {3:F2} mm — kleinere Platten verwenden.", "Ta scena potrzebuje {0:F2} GB pamięci wideo, masz {1:F2} GB (60 % z {2:F2} GB karty — powyżej solwer sam odmówi). Nie mieści się nawet przy najgrubszym odstępie {3:F2} mm — zmniejsz płyty." } },
		{ "super.refuse.buffer", new string[5] { "Один буфер решателя ({0}) просит {1:F0} МиБ одним куском, а видеокарта выдаёт не больше {2:F0} МиБ на один ресурс. Огрубите шаг частиц или уменьшите плиты.", "One solver buffer ({0}) needs {1:F0} MiB in one piece, and the graphics card gives at most {2:F0} MiB per resource. Coarsen the particle spacing or use smaller plates.", "Исәпләгечнең бер буферы ({0}) бер кисәк белән {1:F0} МиБ сорый, ә видеокарта бер ресурска {2:F0} МиБ дан артык бирми. Кисәкчә адымын эреләтегез яки пластиналарны кечерәйтегез.", "Ein Puffer des Lösers ({0}) braucht {1:F0} MiB am Stück, die Grafikkarte vergibt höchstens {2:F0} MiB pro Ressource. Partikelabstand vergröbern oder kleinere Platten verwenden.", "Jeden bufor solwera ({0}) potrzebuje {1:F0} MiB w jednym kawałku, a karta graficzna daje najwyżej {2:F0} MiB na zasób. Zwiększ odstęp cząstek albo zmniejsz płyty." } },
		{ "super.run.chip", new string[5] { "Super: идёт расчёт — {0:F0} %   ·   кадр {1} из {2}   ·   прошло {3}", "Super: solving — {0:F0} %   ·   frame {1} of {2}   ·   elapsed {3}", "Super: исәпләү бара — {0:F0} %   ·   {2} кадрдан {1}   ·   узды {3}", "Super: Berechnung läuft — {0:F0} %   ·   Bild {1} von {2}   ·   vergangen {3}", "Super: trwa obliczanie — {0:F0} %   ·   klatka {1} z {2}   ·   upłynęło {3}" } },
