		{ "super.s40.refuse.region_empty", new string[5] { "В области счёта нет вещества ни одного тела — считать нечего.", "The compute region contains no matter of any body — nothing to compute.", "Санау өлкәсендә бер җисемнең дә матдәсе юк — санарга әйбер юк.", "Im Rechenbereich liegt keine Materie irgendeines Körpers — nichts zu rechnen.", "W obszarze obliczeń nie ma materii żadnego ciała — nie ma czego liczyć." } },
		{ "super.s40.refuse.region_partial", new string[5] { "«{0}» лишь частью слоёв в области счёта — кассета или пакет считается только целиком (слои связаны приводом).", "“{0}” is only partly inside the compute region — a cassette or pack is computed only whole (its layers are tied by the drive).", "«{0}» санау өлкәсендә катламнарының өлеше белән генә — кассета яки пакет бөтен көе генә санала.", "„{0}“ liegt nur mit einem Teil seiner Lagen im Rechenbereich — Kassette oder Paket wird nur ganz gerechnet.", "„{0}” jest w obszarze obliczeń tylko częścią warstw — kaseta lub pakiet liczy się tylko w całości." } },
		{ "super.s40.refuse.first_contact", new string[5] { "Стержень встречает «{0}» раньше области счёта (на {1:F1} мм): вне области вещество не создаётся, и стержень пролетел бы сквозь пустоту. Расширьте область до первого касания.", "The rod meets “{0}” before the compute region (by {1:F1} mm): no matter exists outside the region, so the rod would fly through empty space. Extend the region to the first contact.", "Таяк «{0}» белән санау өлкәсенә кадәр очраша ({1:F1} мм га): өлкәдән тыш матдә юк, таяк бушлык аша очар иде. Өлкәне беренче кагылуга кадәр киңәйтегез.", "Der Stab trifft „{0}“ vor dem Rechenbereich (um {1:F1} mm): außerhalb gibt es keine Materie, der Stab flöge durch Leere. Bereich bis zum ersten Kontakt erweitern.", "Pręt napotyka „{0}” przed obszarem obliczeń (o {1:F1} mm): poza obszarem nie ma materii, pręt przeleciałby przez pustkę. Rozszerz obszar do pierwszego kontaktu." } },
		{ "super.s40.refuse.plate_in_model", new string[5] { "{0} заходит в вещество части «{1}» модели ({2:N0} частиц): два вещества в одном объёме не сцена.", "{0} enters the matter of model part “{1}” ({2:N0} particles): two materials in one volume are not a scene.", "{0} модельнең «{1}» өлеше матдәсенә керә ({2:N0} кисәкчә): бер күләмдәге ике матдә — сәхнә түгел.", "{0} dringt in die Materie des Modellteils „{1}“ ein ({2:N0} Partikel): zwei Stoffe in einem Volumen sind keine Szene.", "{0} wchodzi w materię części modelu „{1}” ({2:N0} cząstek): dwa materiały w jednej objętości to nie scena." } },
