		{ "radar.solve.result", new string[5] { "ЭПР: {0} м²  ({1} дБм²)", "RCS: {0} m²  ({1} dBsm)", "ЭПР: {0} м²  ({1} дБм²)", "RCS: {0} m²  ({1} dBsm)", "RCS: {0} m²  ({1} dBsm)" } },
		{ "radar.solve.counters", new string[5] { "Сетка: {0} лучей · {1} луча/λ · показано путей: {2}", "Grid: {0} rays · {1} rays/λ · displayed paths: {2}", "Челтәр: {0} нур · {1} нур/λ · күрсәтелгән юллар: {2}", "Raster: {0} Strahlen · {1} Strahlen/λ · gezeigte Pfade: {2}", "Siatka: {0} promieni · {1} promieni/λ · widoczne ścieżki: {2}" } },
		{ "radar.solve.too_small", new string[5] { "Размер меньше 3λ. Для резонансов и дифракции нужен волновой решатель.", "Size below 3λ. Resonances and diffraction require a wave solver.", "Үлчәм 3λ дан кечерәк. Резонанслар һәм дифракция өчен дулкын чишүчесе кирәк.", "Größe unter 3λ. Resonanzen und Beugung erfordern einen Wellensolver.", "Rozmiar poniżej 3λ. Rezonanse i dyfrakcja wymagają solvera falowego." } },
		{ "radar.solve.boundary", new string[5] { "Пограничная область 3–20λ: ошибки резонансов и кромок не оценены.", "Transition region 3–20λ: resonance and edge errors are not quantified.", "3–20λ чик өлкәсе: резонанс һәм кыр хаталары бәяләнмәгән.", "Übergangsbereich 3–20λ: Resonanz- und Kantenfehler sind nicht bestimmt.", "Obszar przejściowy 3–20λ: błędy rezonansów i krawędzi nie są określone." } },
		{ "radar.pulse.caption", new string[5] { "Замедление ×{0}. Это анимация рассчитанных путей; прозрачность вторичных лучей — для читаемости.", "Slowed ×{0}. Animation of calculated paths; secondary-ray opacity is a readability aid.", "Әкренәйтү ×{0}. Исәпләнгән юллар анимациясе; икенчел нурларның үтә күренүе — күрсәтү өчен.", "Verlangsamt ×{0}. Animation berechneter Pfade; Transparenz dient der Lesbarkeit.", "Spowolnienie ×{0}. Animacja obliczonych ścieżek; przezroczystość ułatwia odczyt." } },
		{ "radar.heat.scale", new string[5] { "Вклад грани, без взаимного гашения:  −40                 −20                 0 дБ", "Facet contribution, before interference:  −40                 −20                 0 dB", "Грань өлеше, үзара сүнүне исәпләмичә:  −40                 −20                 0 дБ", "Flächenbeitrag, vor Interferenz:  −40                 −20                 0 dB", "Wkład ściany, przed interferencją:  −40                 −20                 0 dB" } },
		{ "radar.propagation.limitations", new string[5] { "Физическая оптика + переотражения, идеальный металл (PEC). Мощность луча: 0 дБ относительно падающего. Покрытия и кромочная дифракция не учтены. Результат описывает сетку, а не настоящий самолёт.", "Physical optics + multiple reflections, perfect conductor (PEC). Ray power: 0 dB relative to incidence. Coatings and edge diffraction omitted. Result describes the mesh, not a real aircraft.", "Физик оптика + кабат чагылышлар, идеаль металл (PEC). Нур куәте: төшүче нурга карата 0 дБ. Капламалар һәм кыр дифракциясе исәпләнми. Нәтиҗә чын очкычны түгел, челтәрне тасвирлый.", "Physikalische Optik + Mehrfachreflexionen, idealer Leiter (PEC). Strahlleistung: 0 dB relativ zum Einfall. Ohne Beschichtungen und Kantenbeugung. Ergebnis gilt für das Netz, nicht für ein reales Flugzeug.", "Optyka fizyczna + wielokrotne odbicia, idealny przewodnik (PEC). Moc promienia: 0 dB względem padającego. Bez powłok i dyfrakcji krawędziowej. Wynik opisuje siatkę, nie prawdziwy samolot." } },
